(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c36"]=[{"id":"00007272","register_sub_id":"101","register_pk":"108254","name":"上善寺本堂","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41353884,"lng":135.31697886,"geo_status":"db","era":"天和3／宝暦5改修","year":1683,"year_source":"db","year_min":1683,"year_max":1683,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積380㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0501","desc":"境内のほぼ中央に西面して建つ。入母屋造本瓦葺の七間堂で、正面に一間向拝を付ける。内・外陣からなる典型的な浄土宗平面に、正面に広縁、両側面入側一間半に各３室を設ける特徴的な平面になる。正面各間には両開双折桟唐戸をたてる。大規模な浄土宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007272"},{"id":"00007273","register_sub_id":"101","register_pk":"108255","name":"上善寺庫裏","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41358338,"lng":135.31664475,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0502","desc":"本堂の西北に南面して建つ。南北棟の切妻造妻入本瓦葺で、正面１４ｍ奥行１６ｍと規模の大きな庫裏である。東側面には桁行５．６ｍ梁間９．０ｍの切妻屋根を張り出し、その南面に式台を付ける。棟に煙出を載せ、妻正面には虹梁や束、貫からなる架構を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007273"},{"id":"00007275","register_sub_id":"101","register_pk":"108257","name":"上善寺鐘楼","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.413242,"lng":135.31694,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造、瓦葺、面積16㎡","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0504","desc":"本堂の南方に位置する南北棟の吹放ち鐘楼で、屋根は切妻造本瓦葺。桁行３．９ｍ梁間３．６ｍ、切石積基壇上に四方転びに円柱を建て、貫や台輪で固める。三斗組で、妻は虹梁大瓶束、軒は二軒繁垂木。笈形や木鼻、中備などに貘や獅子ほかの良質な彫物が配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007275"},{"id":"00007276","register_sub_id":"101","register_pk":"108258","name":"上善寺表門","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.413349,"lng":135.316544,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0505","desc":"本堂の正面、通りに西面して建つ。切妻造本瓦葺の四脚門で、間口３．５ｍに及ぶ。本柱は円柱で、その前後に方柱を建てる。組物は三斗組で、妻は虹梁大瓶束。軒は二軒繁垂木。中央に両開桟唐戸をたてる。組物間や扉上部等が植物紋様や動物の彫刻で充たされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007276"},{"id":"00007277","register_sub_id":"101","register_pk":"108259","name":"上善寺裏門","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41359473,"lng":135.316483,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.5m、両脇袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0506","desc":"庫裏の西、孝子越街道に北面する。切妻造本瓦葺の一間薬医門。間口２．５ｍで、両脇に袖塀を設け、東袖塀に潜りを開ける。本柱は五平柱で、控柱は面取方柱。一軒半繁垂木。妻と冠木中備に板蟇股を置く。旧佐野町場の町並みに建つ、重厚な門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007277"},{"id":"00006242","register_sub_id":"101","register_pk":"107226","name":"斑鳩寺聖徳殿後殿","kana":"いかるがでらしょうとくでんこうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県揖保郡太子町鵤709","lat":34.8369963,"lng":134.5751897,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0282","desc":"３層の屋根を重ねた八角円堂の外観で，中殿取合い部の南北に入母屋造翼部を突出。上層は三手先に扇垂木，中間の庇は平三斗に疎垂木，下層は出組に繁垂木と変化を付ける。内部は中殿に面して唐破風を飾り，中央に厨子を納める。伊藤平左衛門設計の近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006242"},{"id":"00006241","register_sub_id":"101","register_pk":"107225","name":"斑鳩寺聖徳殿中殿","kana":"いかるがでらしょうとくでんなかでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県揖保郡太子町鵤709","lat":34.83700696,"lng":134.57532689,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0281","desc":"聖徳殿は境内南寄りに東面して建つ。中殿は前殿と後殿を繋ぐ両下造の本瓦葺。梁間４間の身舎が二重折上格天井の内陣で，両側面の裳階は廊下とする。両妻の柱は前殿と後殿の柱を兼用し，内部空間は実質桁行５間規模となる。伊藤平左衛門設計の近代仏堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006241"},{"id":"00015207","register_sub_id":"101","register_pk":"530631","name":"雲松寺玄関及び庫裏","kana":"うんしょうじげんかんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市河間町19","lat":34.84463611,"lng":134.69969167,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0822","desc":"本堂の東に南面して建つ玄関及び庫裏。入母屋造の東西棟の玄関棟に南北棟の庫裏が接続し全体にＬ字の平面。玄関は正面に唐破風屋根の式台を付し、庫裏は南西を土間、北に２列６室を配す。北・西庭を望む座敷は室境に雁・松・竹・梅の襖絵を建てる瀟洒な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015207"},{"id":"00015208","register_sub_id":"101","register_pk":"530632","name":"雲松寺山王堂","kana":"うんしょうじさんのうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市河間町19他","lat":34.84441944,"lng":134.69973889,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0823","desc":"本堂南東に位置し山王権現を祀る小堂。南面して建つ桁行三間、梁間三間半、入母屋造本瓦葺で一間向拝を付す。組物は舟肘木、軒は一軒疎垂木、妻飾は虹梁大瓶束。内部は内・外陣とし内陣背面中央の仏壇上に宮殿を配す。正面にガラス戸を建てた近代らしい仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015208"},{"id":"00015209","register_sub_id":"101","register_pk":"530633","name":"雲松寺山門及び袖塀","kana":"うんしょうじさんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市河間町17","lat":34.84431111,"lng":134.69975833,"geo_status":"db","era":"江戸中期／大正4年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"山門 木造2階建、瓦葺、建築面積12㎡ 袖塀 土塀、総延長21m","structure_material":"山門 木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0824","desc":"境内入口に東面して建つ一間一戸入母屋造本瓦葺の鐘楼門と南北に続く土塀。山門下層は四隅に角柱と円柱を一対で立てる特異な形式。上層は円柱を立て組物は尾垂木付二手先、軒は二軒繫垂木、腰組付縁に高欄を付す。凝ったつくりの山門で境内の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015209"},{"id":"00015206","register_sub_id":"101","register_pk":"530630","name":"雲松寺本堂","kana":"うんしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市河間町19","lat":34.84458611,"lng":134.69943889,"geo_status":"db","era":"宝暦元年(1751)／江戸後期・大正14年改修","year":1751,"year_source":"db","year_min":1751,"year_max":1751,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積242㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0821","desc":"姫路城北方にある黄檗宗寺院の本堂。基壇上に建つ入母屋造本瓦葺の四周に裳階を付し、大棟に宝珠を飾る。身舎組物は平三斗で一軒扇垂木、妻飾は二重虹梁蟇股。六間取後列中央の内陣は格天井で須弥壇を配す。播磨地方の黄檗宗寺院の代表的な建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015206"},{"id":"00010327","register_sub_id":"101","register_pk":"199100","name":"慧日寺裏門","kana":"えにちじうらもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077584,"lng":135.069003,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、銅板葺、間口2.3m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"28-0606","desc":"庫裏の東正面に建つ、間口二・三メートルの一間薬医門。軒は一軒疎垂木の木舞打ち、切妻造銅板葺である。五平の本柱上に冠木、控柱間に絵様木鼻付頭貫を渡し、前後に三筋の梁をかける。全体に簡素なつくりであるが、江戸中期復興の境内北側の構えを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010327"},{"id":"00010325","register_sub_id":"101","register_pk":"199098","name":"慧日寺経蔵","kana":"えにちじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077693,"lng":135.069541,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積39㎡、経庫付","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0604","desc":"方丈の東正面に、西面して建つ。置き屋根式の切妻造桟瓦葺、平入の土蔵造で、正面入口には持送りで入母屋造の庇を設ける。内部は南北に二分して南側四・九メートル四方を吹抜けとし、奥に須弥壇を構え、扇垂木の軒をもつ宮殿風経庫を置く、類例の少ない経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010325"},{"id":"00010324","register_sub_id":"101","register_pk":"199097","name":"慧日寺庫裏","kana":"えにちじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077916,"lng":135.069148,"geo_status":"db","era":"江戸後期／大正13年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積373㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0603","desc":"桁行二三メートル梁間一五メートル、東西棟の入母屋造茅葺、妻入りで、方丈の北に建つ。正面となる東側を土間とし、居室部は棟通りを境に南北二列に分け、背面側は八畳三室を配し、南西隅の書院には座敷飾を設ける。方丈とともに境内空間の核を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010324"},{"id":"00010326","register_sub_id":"101","register_pk":"199099","name":"慧日寺鐘楼","kana":"えにちじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077785,"lng":135.069383,"geo_status":"db","era":"慶応3年（1867）","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、檜皮葺、建築面積5.9㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0605","desc":"方丈の南、低い乱石積基壇に東西棟で建つ袴腰付の方一間形式で、入母屋造檜皮葺である。梁を現しとして銅鐘を吊り、その上で化粧隅木尻を組み、化粧屋根裏とする。軒は二軒繁垂木である。二手先詰組とした縁腰組も充実し、たちが高く存在感のある鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010326"},{"id":"00010323","register_sub_id":"101","register_pk":"199096","name":"慧日寺方丈","kana":"えにちじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077654,"lng":135.069077,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積349㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0602","desc":"丘陵を背にして東に開く境内奥中央に東面して建つ。入母屋造茅葺で、六間取の正側面に広縁を廻らした平面とし、軸部は角柱で直接桁を受ける。南東の仏殿とは橋状の矩折れ渡廊下で繋ぎ、北の庫裏とは式台玄関付廊下で連絡する。地域景観の核となる茅葺の方丈。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010323"},{"id":"00011165","register_sub_id":"101","register_pk":"205272","name":"大土神社蔵","kana":"おおつちじんじゃくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.73514,"lng":135.231277,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0648","desc":"幣殿及び拝殿の西側に建つ、神事道具等を収めるための蔵。土蔵造平屋建で、拝殿側妻面に扉口を開き、背面上部に換気のための丸穴を設ける以外は全面壁とする。内壁は真壁漆喰塗、外壁はモルタル塗。境内景観を構成する小規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011165"},{"id":"00011166","register_sub_id":"101","register_pk":"205273","name":"大土神社鳥居","kana":"おおつちじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.734477,"lng":135.231439,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、高さ5.2m、間口4.1m","structure_material":"石造","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0649","desc":"南北に細長い敷地の南端にあって境内を画する。間口四・一メートル、高さ五・二メートルの石造明神鳥居で、六甲花崗岩を用いた粗面仕上げとする。比較的大規模な鳥居である。水車利用を意図して開発され菜種や綿実の絞油生産で栄えた地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011166"},{"id":"00011162","register_sub_id":"101","register_pk":"205269","name":"大土神社拝殿及び幣殿","kana":"おおつちじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.735135,"lng":135.231364,"geo_status":"db","era":"昭和4頃／昭和60頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0645","desc":"正面三間奥行二間の拝殿と奥行四間の幣殿からなる。拝殿は桟瓦葺、幣殿は向唐破風の鉄板葺とする。拝殿は舟肘木に疎垂木で簡明な意匠とする。内部はいずれも一室で、床は板張り。天井は幅の広い格天井を張るなど、簡素な中にも質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011162"},{"id":"00011161","register_sub_id":"101","register_pk":"205268","name":"大土神社本殿","kana":"おおつちじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.735215,"lng":135.231359,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0644","desc":"六甲川に沿った細長い南北敷地の北寄りに建つ。一間社流造で、内陣は三室に区画し、正側面に縁を廻し高欄を付け、正面には浜床・浜縁を設ける。正面は格子戸四枚引違で、軸部組物は檜材を用いる。江戸末期の新田開発の歴史を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011161"},{"id":"00006168","register_sub_id":"101","register_pk":"107152","name":"尾上神社随身門","kana":"おのえじんじゃずいしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.74353042,"lng":134.82443495,"geo_status":"db","era":"江戸後期／大正期・平成7改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0269","desc":"木造，三間一戸八脚門，入母屋造，銅板葺。角柱を長押で固め，虹梁形の飛貫上に蟇股を載せる。軒は一軒半繁垂木。正面中央間に両開戸を吊り，両脇間は板壁で囲い，両脇間後室に随身像を向き合わせに安置する。境内入口に建ち，神社正面の重厚な構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006168"},{"id":"00006167","register_sub_id":"101","register_pk":"107151","name":"尾上神社拝殿","kana":"おのえじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.743721,"lng":134.824097,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0268","desc":"社殿の最前に建つ。木造，桁行５間，梁間４間で，背面に太鼓橋及び神饌所が附属し，入母屋造，正面千鳥破風及び軒唐破風付，本瓦葺とする。破風妻飾は木連格子。屋根には鯱や鬼瓦等の役物瓦を多用し，社殿正面を飾るなど，重厚かつ華やかな外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006167"},{"id":"00006166","register_sub_id":"101","register_pk":"107150","name":"尾上神社幣殿","kana":"おのえじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.743748,"lng":134.82402,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0267","desc":"本殿前面に付設して建つ。木造平屋建，桁行３間，梁間３間，入母屋造，本瓦葺とし，正面に千鳥破風を付け，背面に入母屋屋根を付ける。妻飾は正面以外を木連格子として拝殿と意匠を合わせる。本殿側に祝詞座を設け，規模が大きく，屋根のつくりも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006166"},{"id":"00006165","register_sub_id":"101","register_pk":"107149","name":"尾上神社本殿","kana":"おのえじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.743813,"lng":134.823929,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0266","desc":"加古川河口近くに所在する神社。境内入口正面に社殿が建ち，本殿はその最奥に位置する。木造，三間社流造，銅板葺。庇側面を板壁とし，前面を幣殿の祝詞座に接続する。妻は二手先の組物で，妻飾を二重虹梁大瓶束の形式とし，本格的な神社本殿のつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006165"},{"id":"00010855","register_sub_id":"101","register_pk":"201690","name":"温泉寺薬師堂","kana":"おんせんじやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字薬師畷985-2","lat":35.62563767,"lng":134.80299803,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0625","desc":"温泉街奥寄りに位置する下段境内の中心仏堂。正面三間側面四間、一間向拝付。内部を前後に二分して内陣奥に須弥壇を置き、近世密教系仏堂の一類型を示す。内外の要所を彫刻で飾り、特に向拝は、虹梁上の龍、柱上に並置した籠彫の手挟など、いずれも秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010855"},{"id":"00010865","register_sub_id":"101","register_pk":"201700","name":"春日神社本殿","kana":"かすがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市本郷字口ノ坪141-1","lat":35.158842,"lng":135.264396,"geo_status":"db","era":"弘化3","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0635","desc":"山間の境内上段に西面する覆屋内に建つ。三間社流造、軒唐破風付で、庇は中柱を省き一間とする。三方に縁を廻らし、妻は出組で二重虹梁の妻飾を受ける。彫刻は中井清次郎正用の作になり、向拝廻りの龍や鳳凰の濃密かつ躍動的な彫刻に彫物師中井家の作風を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010865"},{"id":"00001137","register_sub_id":"101","register_pk":"102127","name":"光明寺本堂","kana":"こうみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加東市光明寺433","lat":34.94854619,"lng":134.94726723,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積331㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0053","desc":"安政６年焼失した本堂を武田五一の設計により大正１４年に再興したもの。銅板葺入母屋造の五間堂で、四周に縁を回し、正面に３間の向拝をのばす。内部は１間幅の外陣、２間幅の内陣、２間幅の宮殿とで構成される。鎌倉時代の建築様式に倣ったとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001137"},{"id":"00009522","register_sub_id":"101","register_pk":"194315","name":"極樂寺仁王門","kana":"ごくらくじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町八千代区中野間字門上213-3","lat":35.00732252,"lng":134.9006885,"geo_status":"db","era":"享保13年","year":1728,"year_source":"db","year_min":1728,"year_max":1728,"year_label":null,"structure":"木造二階建、瓦葺、建築面積21㎡","structure_material":"木造二階建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0561","desc":"山裾の境内東端に建ち、三間一戸楼門、入母屋造本瓦葺である。下層柱筋の組物は三斗上に舟肘木をおいて天井桁を受け、また皿斗付大斗や肘木鼻の繰形などに大仏様の細部を取入れる。さらに棟通りの虹梁上に瓶を模した大瓶束をおくなど、独特な形態をもつ楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009522"},{"id":"00010856","register_sub_id":"101","register_pk":"201691","name":"極楽寺本堂","kana":"ごくらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字寺ノ谷800-3","lat":35.623908,"lng":134.805226,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0626","desc":"城崎温泉奥寄りの境内に南面する方丈型本堂。六間取の三方に広縁と落縁を廻らし、正面にガラス戸を建て、両端間に火灯窓を開ける。仏間と室中を折上格天井とし、室中両側に竹の節欄間を設け、上間下間とも奥室に床を備える。伝統的平面に近代的要素を備える本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010856"},{"id":"00014882","register_sub_id":"101","register_pk":"519142","name":"西正寺本堂","kana":"さいしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市上坂部三丁目85","lat":34.74803611,"lng":135.42933611,"geo_status":"db","era":"享保7年(1722)／江戸後期増築","year":1722,"year_source":"db","year_min":1722,"year_max":1722,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0796","desc":"ＪＲ塚口駅南東にある浄土真宗本願寺派の寺院本堂。桁行７間梁間７間入母屋造本瓦葺で正面に１間向拝を付す。外陣正側面に縁を廻し、奥に内陣と両脇に余間をとる中規模真宗本堂の典型。角柱を１間毎に配するなど古式。集落の中心寺院として歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014882"},{"id":"00002966","register_sub_id":"101","register_pk":"103956","name":"志方八幡神社社務所蔵","kana":"しかたはちまんじんじゃしゃむしょくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市志方町志方町301-2","lat":34.823872,"lng":134.829025,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0104","desc":"社務所主屋北西部の北方に建つ。桁行２間半，梁間２間規模の２階建土蔵で，屋根は南北棟，切妻造，桟瓦葺，置屋根形式とし，東面の南寄りに庇を付けた出入口を設ける。土壁をあらわした簡素な外観は社務所主屋背後の裏庭空間の点景をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002966"},{"id":"00002965","register_sub_id":"101","register_pk":"103955","name":"志方八幡神社社務所主屋","kana":"しかたはちまんじんじゃしゃむしょしゅおく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市志方町志方町301-2","lat":34.823776,"lng":134.829178,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺一部瓦葺、建築面積337㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0103","desc":"志方町中心部の宮山頂部近くに南面して建つ。桁行８間，梁間４間の入母屋造，茅葺身舎の南面・西面に本瓦葺の庇を廻した四方蓋風民家の外観と，方丈風の六間取の西方下手に土間及び納屋等を配置し，北東に矩折れに４室を張り出した平面に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002965"},{"id":"00002967","register_sub_id":"101","register_pk":"103957","name":"志方八幡神社社務所門","kana":"しかたはちまんじんじゃしゃむしょもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県加古川市志方町志方町301-2","lat":34.82325,"lng":134.829147,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0105","desc":"社務所主屋式台玄関の南方に位置し，社務所敷地の南辺のほぼ中央に建つ。東西棟，切妻造，桟瓦葺，１間１戸の薬医門で，農家風の主屋に対応した簡素なつくりとする。間口１間規模と小規模ではあるが，石段の上に建ち神社景観のアイストップともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002967"},{"id":"00001136","register_sub_id":"101","register_pk":"102126","name":"慈眼寺持宝院大師堂","kana":"じげんじじほういんたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市社1369","lat":34.91889128,"lng":134.96512145,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積145㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0052","desc":"武田五一設計による木造寺院建築。施工は小西瀧次郎。亀甲積基壇に建つ正面３間、側面５間、正方形平面の堂で、本瓦葺宝形屋根を架ける。異様に長い１間向拝が特徴的で、武田五一の伝統的建築に対する独自な解釈がよく表明されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001136"},{"id":"00006568","register_sub_id":"101","register_pk":"107551","name":"常楽寺山門","kana":"じょうらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.79485151,"lng":134.829376,"geo_status":"db","era":"明和7","year":1770,"year_source":"db","year_min":1770,"year_max":1770,"year_label":null,"structure":"木造、瓦葺、間口3.8m","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0279","desc":"境内の南辺西寄りに建つ間口１２尺の四脚門で，切妻造，本瓦葺とする。妻飾りは虹梁に笈形付大瓶束で，大瓶束に差した桁行の虹梁が特徴。組物は出三斗に実肘木とし，軒は二軒繁垂木である。扉は冠木と唐居敷に軸を納める古式で，八双，四葉の金物もよく遺る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006568"},{"id":"00006569","register_sub_id":"101","register_pk":"107552","name":"常楽寺鐘楼","kana":"じょうらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.79484009,"lng":134.82927317,"geo_status":"db","era":"宝暦4","year":1754,"year_source":"db","year_min":1754,"year_max":1754,"year_label":null,"structure":"木造、瓦葺、面積8.4㎡","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0280","desc":"境内の南方，山門の西に位置する。石積の基壇上に建つ桁行９．５尺，梁間９尺規模の東西棟で，切妻造，本瓦葺とする。柱は四方転びで頭貫を虹梁につくる。組物は出三斗，中備は蟇股，妻飾りは虹梁に蟇股。一軒疎垂木の化粧軒裏とし，棟木下の虹梁に梵鐘を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006569"},{"id":"00006600","register_sub_id":"101","register_pk":"107583","name":"常楽寺本堂","kana":"じょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.795162,"lng":134.829346,"geo_status":"db","era":"元禄5／享保7増築","year":1692,"year_source":"db","year_min":1692,"year_max":1692,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積374㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0277","desc":"本堂は境内西寄りに南面して建つ。桁行１９ｍ，梁間１７ｍ，入母屋造，本瓦葺で向拝が付く。前面を広縁とし，凸形内陣と両脇間，外陣からなる浄土宗本堂である。内陣格天井の花鳥画が鮮やか。増築の本玄関は本堂の東に続く東西棟で，唐破風の式台を南面させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006600"},{"id":"00006567","register_sub_id":"101","register_pk":"107550","name":"常楽寺薬師堂","kana":"じょうらくじやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.794941,"lng":134.829178,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0278","desc":"本堂南に東面して建つ。方２間規模の宝形造，銅板葺で，向拝が付く。石階４級を設け，東，南，北に縁が付く。組物は出三斗で中備は蟇股，一軒疎垂木とする。正面は中央と北間を嵌殺し格子戸とし，南間を開戸とする。内部は板床で，奥の段に厨子を安置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006567"},{"id":"00012593","register_sub_id":"101","register_pk":"367887","name":"真宗大谷派姫路船場別院本徳寺行在所","kana":"しんしゅうおおたにはひめじせんばべついんほんとくじあんざいしょ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市地内町1-1","lat":34.833889,"lng":134.682938,"geo_status":"geocoded","era":"江戸末期／明治18年・昭和8年改修、平成23年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"28 － 0698","desc":"明治天皇の行在所となった御殿で、境内西辺に南面して建つ。桁行六間梁間五間半、入母屋造桟瓦葺で、四周に銅板葺下屋を廻す。内部の中心をなす玉座の間は付書院に天袋と違棚を配した奇抜な座敷飾をもつ。端正な意匠と造作で整えられた寺院附属の住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012593"},{"id":"00008156","register_sub_id":"101","register_pk":"132597","name":"大信寺本堂","kana":"だいしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加西市北条町北条字江ノ木1256","lat":34.93483435,"lng":134.83083663,"geo_status":"db","era":"弘化2年（1845）／平成4年改修","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積219㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0454","desc":"南面して建つ三間堂で、入母屋造銅板葺とし、正面に一間向拝を付ける。側柱が方柱、内部が円柱。組物は出三斗で、中備に成の高い皿斗付出三斗を飾る。外陣及び内陣、脇陣からなる標準的な浄土宗本堂で、室境を簡略化するなど幕末らしい内部構成を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008156"},{"id":"00012773","register_sub_id":"101","register_pk":"367676","name":"多田神社宝物殿","kana":"ただじんじゃほうもつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川西市多田院多田所町1","lat":34.86099389,"lng":135.40307694,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造一部木造平屋建、銅板葺、建築面積138㎡","structure_material":"鉄筋コンクリート造一部木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 708","desc":"猪名川中流の北岸にある境内前方の参道東脇に建つ。切妻造銅板葺の平屋建で、主体部は鉄筋コンクリート造、屋根と切妻造妻入の向拝は木造とする。内部は一室で内装を木造とし、格天井を張る。大正以降戦前に建築された不燃構造・和風意匠の神社宝物殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012773"},{"id":"00014655","register_sub_id":"101","register_pk":"515197","name":"徳壽院本堂","kana":"とくじゅいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区宮内字小松原195他","lat":34.79628889,"lng":134.590925,"geo_status":"db","era":"江戸中期／明治33年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"28 - 0792","desc":"魚吹八幡神社の東隣にある真言宗寺院の本堂。境内北辺西寄りに南面し、切石積基壇上に建つ正面一間、側背面二間の宝形造本瓦葺で縁を付す。組物出組に支輪を備え、軒は二軒扇垂木。内部北辺に仏壇を配して格天井を張る。小規模ながら軒廻りなど充実した造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014655"},{"id":"00014656","register_sub_id":"101","register_pk":"515198","name":"徳壽院薬師堂","kana":"とくじゅいんやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区宮内字小松原195他","lat":34.79628889,"lng":134.59085278,"geo_status":"db","era":"江戸中期／大正4年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"28 - 0793","desc":"魚吹八幡神社の東隣にある真言宗寺院の仏堂。境内北西隅に南面し、方三間の入母屋造平入本瓦葺で南に向拝を付す。軒廻りは柱頭から腕木を出した出桁造で、一軒疎垂木とし珍しい。内部は北に仏壇を設け、床は畳敷で竿縁天井を張る。簡素ながらも丁寧な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014656"},{"id":"00007091","register_sub_id":"101","register_pk":"108073","name":"泊神社本殿","kana":"とまりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764275,"lng":134.824326,"geo_status":"db","era":"承応2","year":1653,"year_source":"db","year_min":1653,"year_max":1653,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.0㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0347","desc":"南面する入母屋造妻入銅板葺で、正面に軒唐破風付の向拝を付ける特徴的な外観となる。１間社で、背面は中央に柱を建て２間とし、正・側３方に榑縁をまわす。身舎は円柱で、柱上は出組。向拝は三斗組で、中備に蟇股を置く。時代相応の良質な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007091"},{"id":"00002663","register_sub_id":"101","register_pk":"103653","name":"長田神社天照社","kana":"ながたじんじゃあまてらすしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67158623,"lng":135.1469122,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0082","desc":"透塀の内，本殿東方に位置し，切石３段積の基壇上に建つ。一間社流造で，桁行２尺７寸，梁間２尺２寸，向拝梁間１尺８寸規模，屋根は銅板葺，軒は一軒繁垂木とする。本殿の意匠に対応して，柱は円柱で四周に縁高欄を廻し，向拝の柱は角柱として浜床を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002663"},{"id":"00002666","register_sub_id":"101","register_pk":"103656","name":"長田神社出雲大社","kana":"ながたじんじゃいずもたいしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67146475,"lng":135.14662289,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0085","desc":"焼失を免れた末社のひとつで，西楽所の西方に東面して建つ。玉垣内の石積基壇上に載った一間社流造で，桁行２尺４寸，梁間３尺３寸規模とし，月読社と同様，軒は二軒繁垂木，三方に高欄付縁を廻し，棟を千木と勝男木で飾る。拝殿等に合わせ木部を丹塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002666"},{"id":"00002671","register_sub_id":"101","register_pk":"103661","name":"長田神社廻廊及び脇門","kana":"ながたじんじゃかいろうおよびわきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.6711873,"lng":135.14720031,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積60㎡、脇門付","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0090","desc":"神門の西側４間分，神符授与所の東側，脇門を挟んで左右４間分づつを廻廊とする。梁間８尺，両下造，銅板葺で，北側は吹放ち，南面は腰羽目板嵌，上部連子窓とし，脇門には桟唐戸を建込む。神門などともに石垣上に建ち，内外苑を隔てる一文字状の結界をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002671"},{"id":"00002672","register_sub_id":"101","register_pk":"103662","name":"長田神社神楽殿","kana":"ながたじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67133872,"lng":135.14725708,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0091","desc":"脇門を潜った右手前方，拝殿の東南方に西面して建つ。桁行２１尺梁間１２尺，入母屋造，銅板葺で，前後に桁行９尺，梁間４尺５寸と６尺の突出部を設け十字形平面とする。軒は一軒疎垂木とし，四周に縁高欄を廻す。神社社殿構成に欠くことのできない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002672"},{"id":"00002670","register_sub_id":"101","register_pk":"103660","name":"長田神社神符授与所及び附属屋","kana":"ながたじんじゃしんふじゅよじょおよびふぞくや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67118053,"lng":135.1470848,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0089","desc":"神門東端に桁行６尺，梁間８尺，東西棟，両下造の附属屋が取り付き，その東に南北棟，入母屋造，桁行１８尺，梁間１２尺の神符授与所を内苑側に張り出す。北側は三方にガラス障子を建込み，南面は附属屋とも廻廊と同様の腰羽目板嵌，上部連子窓の意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002670"},{"id":"00002669","register_sub_id":"101","register_pk":"103659","name":"長田神社神門","kana":"ながたじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67116409,"lng":135.14700075,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、間口7.1m","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0088","desc":"拝殿の南方，拝殿の棟とは方向をやや振って建つ。境内再編に伴う新設の施設で，切妻造，銅板葺，３間３戸の八脚門形式を採る。本柱は円柱，控柱は角柱，軒は二軒疎垂木とし，丹塗のうえ要所を錺金具で飾る。昭和初期内務省系神社建築の造形的特色をもつ作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002669"},{"id":"00002662","register_sub_id":"101","register_pk":"103652","name":"長田神社透塀及び門","kana":"ながたじんじゃすきべいおよびもん","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67165612,"lng":135.14680245,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0081","desc":"東西楽所から発して本殿を囲うように建つ。塀は東西面各８間，北面１０間の切妻造，銅板葺，控え柱建で，腰羽目板張り，上部透し連子窓とする。東西楽所寄りの２箇所に潜りを設けるほか，北面中央に切妻造，銅板葺，柱間７尺５寸，棟門形式の裏門を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002662"},{"id":"00002665","register_sub_id":"101","register_pk":"103655","name":"長田神社月読社","kana":"ながたじんじゃつくよみしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.671494,"lng":135.147171,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0084","desc":"焼失を免れた末社のひとつで，拝殿の東方に西面して建つ。一間社流造，銅板葺で，桁行２尺４寸，梁間２尺３寸，向拝梁間１尺９寸規模，軒は二軒繁垂木とし，三方に高欄付縁を廻す。もと素木建であったが，玉垣内の新設石積基壇上に移築され，丹塗を施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002665"},{"id":"00002661","register_sub_id":"101","register_pk":"103651","name":"長田神社西楽所","kana":"ながたじんじゃにしがくじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67146627,"lng":135.14677447,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0080","desc":"拝殿の背面１間通りの西端に位置し，拝殿よりやや低い石積基壇の上に建つ。桁行２間，梁間２間規模の東西棟，銅板葺，入母屋造とし，西・南面に連子窓，東面に入口を開ける。東楽所と同様なつくりになり，社殿構成に拡がりと奥行きをもたせる役割を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002661"},{"id":"00002659","register_sub_id":"101","register_pk":"103649","name":"長田神社拝殿","kana":"ながたじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67139874,"lng":135.14690657,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0078","desc":"幣殿の前面に建つ。幣殿とは平面的に一体のつくりで，桁行５間，梁間５間，銅板葺の入母屋造とする。正面１間通りは吹放ちの向拝とし縋破風をつけて納めるなど創意が見られるほか，正面中央の軒唐破風，飛貫頭貫間の蟇股など社殿中最も装飾的につくられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002659"},{"id":"00002660","register_sub_id":"101","register_pk":"103650","name":"長田神社東楽所","kana":"ながたじんじゃひがしがくじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67150982,"lng":135.14697797,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0079","desc":"拝殿の背面１間通りの東端に位置し，拝殿よりやや低い石積基壇の上に建つ。桁行２間，梁間２間規模の東西棟，銅板葺，入母屋造とし，東・南面に連子窓，西面に入口を開ける。組物は舟肘木，軒は一軒疎垂木で簡素であるが本殿幣殿拝殿の社殿構成の一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002660"},{"id":"00002667","register_sub_id":"101","register_pk":"103657","name":"長田神社蛭子社","kana":"ながたじんじゃひるこしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67138985,"lng":135.14664363,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積0.79㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0086","desc":"焼失を免れた末社のひとつで，拝殿の西方に東面して建つ。出雲大社とは並列し，ほぼ同様の仕様であるが，桁行２尺３寸，梁間２尺１寸１分，向拝梁間１尺５寸９分，棟高１０尺９寸４分とやや小ぶり。もと素木建であったが，移築に際し丹塗仕上げとされた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002667"},{"id":"00002658","register_sub_id":"101","register_pk":"103648","name":"長田神社幣殿","kana":"ながたじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67148973,"lng":135.14688133,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0077","desc":"本殿と拝殿を繋ぐ位置に建つ。東西棟の本殿とは棟を直交させた切妻造で，桁行２間（１３尺５寸）梁間１間（１４尺４寸）の規模とする。柱は角柱，組物は出三斗で中備に蟇股を入れ，軒は二軒疎垂木とするなど本殿とは異なる仕様とし桁行柱間には蔀戸を立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002658"},{"id":"00002657","register_sub_id":"101","register_pk":"103647","name":"長田神社本殿","kana":"ながたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67156657,"lng":135.14685498,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0076","desc":"大正１３年１月焼失の再建社殿。三間社流造で，切石積基壇上の亀腹上に建ち，柱は円柱で四方に跳高欄付切目縁を廻らす。組物は平三斗，軒は二軒繁垂木，妻飾は豕叉首とし，棟を千木と勝男木で飾る。木部は丹塗を施し要所に錺金具を打つ。設計は香川定太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002657"},{"id":"00002668","register_sub_id":"101","register_pk":"103658","name":"長田神社松尾社","kana":"ながたじんじゃまつおしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.671444,"lng":135.147186,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積0.81㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0087","desc":"焼失を免れた末社のひとつで，火災前は覆舎内に在った。拝殿向拝部の東方，月読社の南方に位置し，桁行２尺３寸，梁間２尺１寸と対向する蛭子社と同規模，同仕様であるが，石積基壇上に亀腹を築き，その上に一間社流造を載せている点は透塀内の末社に似る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002668"},{"id":"00009519","register_sub_id":"101","register_pk":"194312","name":"西宮神社嘉永橋","kana":"にしのみやじんじゃかえいばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73525384,"lng":135.33442382,"geo_status":"db","era":"嘉永元年","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"石造桁橋、橋長6.0m、幅員1.8m、袖高欄付","structure_material":"石造桁橋","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0558","desc":"神池の西側中央に架かり、松尾神社の参道上に位置する。石造、橋長六・〇メートル、幅員一・八メートルの通行用の桁橋で、六甲山産の花崗岩（御影石）が用いられる。敷石の上には石製の欄干を備える。境内に残る最も古い橋で、神社の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009519"},{"id":"00009518","register_sub_id":"101","register_pk":"194311","name":"西宮神社瑞寶橋","kana":"にしのみやじんじゃすいほうばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73545371,"lng":135.33460228,"geo_status":"db","era":"明治40年／大正11年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造桁橋、橋長5.5m、幅員2.5m、袖高欄付","structure_material":"石造桁橋","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0557","desc":"社殿前につくられた神池に架かり、拝殿正面に位置する。石造、橋長五・五メートル幅員二・五メートルの祭礼用の太鼓橋で、六甲山産の花崗岩（御影石）が用いられる。円弧状の桁石の上を十七等分して敷石を割り付け、青銅製の欄干を備えた丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009518"},{"id":"00015344","register_sub_id":"101","register_pk":"532468","name":"西宮神社手水舎","kana":"にしのみやじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73535833,"lng":135.33507778,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、面積13㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0836","desc":"境内中央部、参道東脇に設けた手水舎。切妻造銅板葺で、四隅の石製台座上に円柱と八角柱を束ねて立て、頭貫で固め、大斗肘木で桁と虹梁を受ける。中備は中世風の復古的な蟇股。内部に手水鉢を据え四方を吹放つ。真反の軒は優美で意匠に凝った堂々たる手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015344"},{"id":"00015345","register_sub_id":"101","register_pk":"532469","name":"西宮神社銅鐘舎（旧燈籠覆屋）","kana":"にしのみやじんじゃどうしょうしゃ（きゅうとうろうおおいや）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73545833,"lng":135.33483056,"geo_status":"db","era":"明治37年","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、面積3.2㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0837","desc":"境内中央部、参道の西脇に位置する旧燈籠陳列用の覆屋。方一間の起付き切妻造銅板葺。壇上積風石製台座に土台を置き、角柱を立て内法長押を廻し、外側絵様付の舟肘木で梁と桁を受ける。四面に菱格子を建て、上部は筬欄間とする。繊細かつ丁寧なつくりの覆屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015345"},{"id":"00015342","register_sub_id":"101","register_pk":"532466","name":"西宮神社西翼殿","kana":"にしのみやじんじゃにしよくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73586111,"lng":135.33448611,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0834","desc":"本殿の西に位置する祭祀用の社殿。方一間切妻造銅板葺で、亀腹上に角柱を立て長押で固め、組物は舟肘木。内部は一室の板敷で上部は化粧屋根裏とし、南・東面に刎高欄付榑縁を廻す。本殿復興に伴い新たに建立した社殿で東翼殿と一対で左右対称の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015342"},{"id":"00015343","register_sub_id":"101","register_pk":"532467","name":"西宮神社拝殿","kana":"にしのみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73570833,"lng":135.33460556,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積215㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0835","desc":"本殿正面に位置する鉄筋コンクリート造の拝殿。入母屋造平入銅板葺で南面に千鳥破風を据え軒唐破風付向拝を付し、北面も軒唐破風を突出する。両脇から北方に翼廊を延ばして斎庭を囲う回廊を形成し、内外で塗装色を塗り分ける。屋根の構成優美で華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015343"},{"id":"00015341","register_sub_id":"101","register_pk":"532465","name":"西宮神社東翼殿","kana":"にしのみやじんじゃひがしよくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73584722,"lng":135.33474722,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0833","desc":"本殿の東に位置し、斎庭に南面する祭祀用の社殿。亀腹基壇に建つ方一間、切妻造銅板葺。角柱を長押で固め、組物は舟肘木。内部は一室の板敷で上部は化粧屋根裏とし、南・西面に刎高欄付榑縁を廻す。本殿の復興に伴い新たに建立した社殿で、斎庭の一角を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015341"},{"id":"00015340","register_sub_id":"101","register_pk":"532464","name":"西宮神社本殿","kana":"にしのみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73590278,"lng":135.33462222,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0832","desc":"全国えびす社総本社の本殿。身舎の前に庇を付した春日造を相の間で三棟並列に連結した大規模な社殿。屋根は銅板葺。組物は大斗絵様肘木で、庇を一連で葺き降ろし、庇両端に隅木を入れる。戦災焼失した旧国宝本殿を戦後に復興した我が国唯一の三連春日造社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015340"},{"id":"00001446","register_sub_id":"101","register_pk":"102436","name":"フロインドリーブ本店（旧ユニオン教会）","kana":"ふろいんどりーぶほんてん（きゅうゆにおんきょうかい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区生田町4-6-15","lat":34.70079804,"lng":135.19514413,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、スレート葺、建築面積463㎡、塔屋付き","structure_material":"鉄筋コンクリート造3階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0061","desc":"ヴォーリズ建築事務所の設計になる教会建築。正面中央の玄関上部に鍾塔を建ち上げ，左手にゴシック式の礼拝堂棟，右手にハーフティンバー・スタイルの牧師館棟を配し，礼拝堂棟の妻面，角塔，牧師館棟の屋根面との構成で街路沿いファサードの均衡をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001446"},{"id":"00011992","register_sub_id":"101","register_pk":"211164","name":"本住寺本堂","kana":"ほんじゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字長崎493-3","lat":35.627563,"lng":134.812214,"geo_status":"db","era":"昭和6年／平成11年増築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"28-674","desc":"城崎温泉街山寄りの境内に南面する本堂。背面中央間に須弥壇、右脇間に開祖の壇、左脇間に位牌堂をそれぞれ張出す。堂内は全て格天井で内陣は折上格天井で荘厳し、来迎柱にも獅子鼻・獏鼻を飾る。向拝の蟇股の龍の彫刻は播州飾磨彫の松本一門の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011992"},{"id":"00003130","register_sub_id":"101","register_pk":"104120","name":"本徳寺中宗堂","kana":"ほんとくじちゅうそうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市亀山324","lat":34.809879,"lng":134.677216,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"28 － 0116","desc":"入母屋造平入の前室と，重層宝形造の後室を複合させた堂宇。前室には向拝１間を備え，全体を本瓦葺とする。江戸末期に焼失した前身堂を再建したもの。九世伊藤平左衛門の作。現存例の少ない中宗堂のひとつで，内陣と外陣を備える本格的複合仏堂の好例である。&nbsp;","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003130"},{"id":"00009521","register_sub_id":"101","register_pk":"194314","name":"楊柳寺仁王門","kana":"ようりゅうじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町八千代区大和字前田776-1","lat":35.00179503,"lng":134.87491299,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造二階建、瓦葺、建築面積20㎡","structure_material":"木造二階建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0560","desc":"境内下段の入口に南面して構える、三間一戸楼門、入母屋造本瓦葺。軸部は貫で固め、上層の組物は二手先、軒は二軒繁垂木である。皿斗付大斗や挿肘木の使用、通肘木鼻の繰形などに、大仏様の影響が認められる。古刹の正門に相応しい、均整のとれた楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009521"},{"id":"00009520","register_sub_id":"101","register_pk":"194313","name":"楊柳寺本堂","kana":"ようりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町八千代区大和字東谷774","lat":35.00350943,"lng":134.87697003,"geo_status":"db","era":"寛延4年／昭和22年改修","year":1751,"year_source":"db","year_min":1751,"year_max":1751,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0559","desc":"境内上段に建つ。桁行五間梁間四間半、向拝一間、入母屋造銅板葺である。梁間二間分の外陣は虹梁四筋を架けて格天井を張り、桁行三間梁間二間の内陣に大型の厨子を安置する。後陣と右脇陣は半間幅の下屋とする。山中に建つ本格的なつくりの天台宗寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009520"},{"id":"00011991","register_sub_id":"101","register_pk":"211163","name":"蓮成寺本堂","kana":"れんじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所452","lat":35.625867,"lng":134.807,"geo_status":"db","era":"昭和11年／昭和57年頃改修、平成19年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"28-673","desc":"城崎温泉山寄りの境内に南面する真宗寺院本堂。昭和八年建立の大本教但州別院鶴鳴殿を移築し向拝と下屋を付したもので、小屋組はキングポストトラスである。西側に一列室を設けたため、向拝が中心よりずれ、西端に花頭窓を穿ち特徴ある外観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011991"},{"id":"00002664","register_sub_id":"101","register_pk":"103654","name":"長田神社八幡社","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67155547,"lng":135.14677378,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0083","desc":"透塀の内，本殿西方に位置する。天照社と同様，切石３段積の基壇上に建つ一間社流造で，桁行２尺７寸，梁間２尺２寸，向拝梁間１尺８寸規模，屋根は銅板葺，軒は一軒繁垂木，木部を丹塗とする。天照社とともに，透塀内の聖なる空間を構成する主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002664"},{"id":"00007097","register_sub_id":"101","register_pk":"108079","name":"泊神社能舞台","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.76390437,"lng":134.82407643,"geo_status":"db","era":"江戸後期／平成19改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0353","desc":"神楽殿の南に位置する。北面して建つ切妻造妻入の能舞台で、西側面に脇座、背面に後座を設け、橋掛が続く。桁行４．９ｍ梁間４．９ｍのほぼ方形で、後座は梁間２．１ｍとする。床は拭板敷で、天井は化粧屋根裏天井で、豪快な梁組を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007097"},{"id":"00007098","register_sub_id":"101","register_pk":"108080","name":"泊神社太鼓倉","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.76396127,"lng":134.82390345,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0354","desc":"神楽殿の西南、随身門の西に位置する。桁行６．４ｍ梁間３．８ｍ規模の木造平屋建。屋根は桟瓦葺で、北面を入母屋造、南面を切妻造とする。北妻面に大きく扉口を設け、他３方は土壁とし、内部は漆喰仕上げ、外は焼板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007098"},{"id":"00007096","register_sub_id":"101","register_pk":"108078","name":"泊神社末社種子神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.76415445,"lng":134.82402194,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積0.25㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0352","desc":"住吉神社本殿の南に東面して建つ。正面０．４５ｍ奥行０．５５ｍの１間社流見世棚造で、住吉神社本殿とほぼ同規模、同形式であり、絵様も似ており、一連で建立されたとみられる。本殿の西方から北にかけて、多くの小祠が建ち並び、豊かな境内景観を創り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007096"},{"id":"00007092","register_sub_id":"101","register_pk":"108074","name":"泊神社神楽殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764179,"lng":134.824234,"geo_status":"db","era":"承応2／昭和63改修","year":1653,"year_source":"db","year_min":1653,"year_max":1653,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0348","desc":"本殿の前方に位置する。入母屋造本瓦葺で、桁行３間梁間３間に四周に高欄付切目縁をまわしたが、背面は室内に改造された。面取方柱で、柱上に舟肘木を置き、軒は一軒疎垂木。正面は引違戸、側面は連子窓とする。本殿と一連で建てられた、近世初頭の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007092"},{"id":"00007093","register_sub_id":"101","register_pk":"108075","name":"泊神社幣殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764221,"lng":134.824295,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0349","desc":"本殿の正面、神楽殿後方に繋がる社殿。梁間は神楽殿と同寸で、桁行は３間。屋根は桟瓦葺で、中央２間は北面が切妻造、南面が両下造、両側面半間を下屋とする。正・背面開放で、側面には窓を開ける。内部は畳敷の１室で、天井は化粧屋根裏とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007093"},{"id":"00007095","register_sub_id":"101","register_pk":"108077","name":"泊神社末社住吉神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764275,"lng":134.824112,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積0.24㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0351","desc":"本殿の西南に東面して建つ。正面０．４５ｍ奥行０．５５ｍ規模の１間社流見世棚造。土台上に身舎柱と向拝柱を建て、身舎は正面を両開戸、側・背面を板壁とし、身舎と向拝間を２段の棚状に造る。向拝は三斗組とし、身舎は大斗肘木とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007095"},{"id":"00007094","register_sub_id":"101","register_pk":"108076","name":"泊神社末社熊野神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764408,"lng":134.824265,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積0.32㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0350","desc":"本殿の北に南面して建つ小祠。正面０．４４ｍ規模の１間社。切妻造鉄板葺であるが、流造の前流を切り縮めたとみられる。身舎は正・側面１間とし、身舎背面柱から向拝柱に直接、虹梁を架ける。組物を平三斗、妻を大瓶束とする。丁寧なつくりになる小祠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007094"},{"id":"00001135","register_sub_id":"101","register_pk":"102125","name":"清水寺客殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97233186,"lng":135.0814389,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積90㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0051","desc":"本坊と大講堂との間に位置し、本坊大広殿より渡廊下で連絡される東西棟の建物。３室構成で、南東西の３面に縁側、北面に廊下を設け、東端北側に便所・浴室を張りだす。本坊の大屋根と著しい対照をなす低平な入母屋屋根が建物の性格を表している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001135"},{"id":"00001134","register_sub_id":"101","register_pk":"102124","name":"清水寺本坊","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97237522,"lng":135.08110782,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積694㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0050","desc":"大講堂へ向かう参道沿いの北側擁壁上の平地西寄りに建ち、東面に大講堂に向けて唐破風の玄関車寄を構える。主体部は南側に大広殿・客僧室を、北側に執事室・居間・台所などの内向き諸室を配し大きな切妻屋根で覆い、南西端に方丈室を張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001134"},{"id":"00001132","register_sub_id":"101","register_pk":"102122","name":"清水寺大講堂","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.9724974,"lng":135.08184881,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積424㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0048","desc":"根本中堂の南方、石段下に南面して建つ。本瓦葺宝形屋根の７間堂で、石積基壇に建ち、組物は出組、軒は二軒繁垂木とし、北面を除く３面に高欄付きの縁を回す。「平安時代後期の建築物にあらはれたる意匠を多分に加味」したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001132"},{"id":"00001133","register_sub_id":"101","register_pk":"102123","name":"清水寺鐘楼","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97274571,"lng":135.08154138,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積57㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0049","desc":"大講堂から根本中堂へ登る石段中途の踊場西方に東面して建つ。本瓦葺入母屋造、下部を袴腰とする伝統的形式に則った鐘楼で、組物は二手先、軒は二軒半繁垂木とし、武田五一意匠、高岡市老子製作所出吹の梵鐘を吊す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001133"},{"id":"00001131","register_sub_id":"101","register_pk":"102121","name":"清水寺根本中堂","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97317533,"lng":135.08190793,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積235㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0047","desc":"大正２年焼失した堂塔伽藍坊舎を武田五一の全山再建計画に基づき伊藤平左衛門の施工により復興したもの。根本中堂は、焼失前の中堂に倣ったと思われる本瓦葺入母屋屋根の五間堂で、四面に縁を回し、正面に軒唐破風付きの３間向拝を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001131"},{"id":"00015067","register_sub_id":"101","register_pk":"529345","name":"育成幼稚園園舎兼日本聖公会櫻井聖保羅教会礼拝堂","kana":"いくせいようちえんえんしゃけんにっぽんせいこうかいさくらいせいぱうろきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市大字桜井70","lat":34.51305833,"lng":135.85022222,"geo_status":"db","era":"昭和5年／昭和55年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"29 - 0362","desc":"ＪＲ桜井駅南東にある園舎兼礼拝堂。木造二階建切妻造桟瓦葺で外壁は下見板張、腰は一部モルタル洗出仕上で、上部に矩形と尖塔アーチ窓を開く。一階は園舎、二階は東西に長い単廊の礼拝堂とし、小屋組はシザートラス。地域が親しむ切妻屋根の園舎兼礼拝堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015067"},{"id":"00002074","register_sub_id":"101","register_pk":"103064","name":"菊水楼表門","kana":"きくすいろうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.682003,"lng":135.834152,"geo_status":"db","era":"江戸期／明治期移築","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造薬医門、瓦葺、間口2.4m","structure_material":"木造薬医門","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0032","desc":"春日大社一の鳥居に突き当たる三条通に面した南側に建つ。圓成寺塔頭の門を明治時代に現在地に移築したと伝える。本瓦葺の薬医門は伝承が首肯されるような風格をもつ建築で，歴史ある料理旅館の表構えに格式を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002074"},{"id":"00002075","register_sub_id":"101","register_pk":"103065","name":"菊水楼庭門","kana":"きくすいろうにわもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.68188966,"lng":135.83429635,"geo_status":"db","era":"江戸期／明治期移築","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造薬医門、瓦葺、間口1.9m","structure_material":"木造薬医門","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0033","desc":"本館玄関廻りから旧本館北側の庭を画する塀に設けた門で，本館の玄関脇に建つ。表門同様，圓成寺塔頭の門を明治時代現在地に移築したと伝え，同じ薬医門形式ながらこちらはやや規模が小さく，桟瓦葺とされている。歴史ある料理旅館の構成要素として相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002075"},{"id":"00013311","register_sub_id":"101","register_pk":"366300","name":"旧慈門院表門（陶原家住宅表門）","kana":"きゅうじもんいんおもてもん（すはらけじゅうたくおもてもん）","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46527778,"lng":135.86288611,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0293","desc":"敷地南辺の石垣上に建つ長屋門。入母屋造桟瓦葺で、中央西寄りに扉を開き、門扉前まで石階段を設ける。門の西を作業場、東を物置とし、東から北へ濡縁を廻らす。扉回りはケヤキの良材を用い、内法に虹梁を架け中備を蟇股とするなど敷地正面を印象付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013311"},{"id":"00013308","register_sub_id":"101","register_pk":"366297","name":"旧慈門院客殿及び庫裏（陶原家住宅主屋）","kana":"きゅうじもんいんきゃくでんおよびくり（すはらけじゅうたくおもや）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46538056,"lng":135.86291111,"geo_status":"db","era":"江戸中期／江戸末期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0290","desc":"旧妙楽寺子院の客殿及び庫裏。切妻造桟瓦葺の東西棟で、西の庫裏を落棟とし四周に下屋を廻す。客殿は東に畳廊下及び３列６室を配し、上手に床付の座敷を置く。庫裏は玄関北の茶の間と西の台所からなる。襖絵も良く残り、近世の妙楽寺子院の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013308"},{"id":"00013310","register_sub_id":"101","register_pk":"366299","name":"旧慈門院小座敷及び土蔵（陶原家住宅小座敷及び土蔵）","kana":"きゅうじもんいんこざしきおよびどぞう（すはらけじゅうたくこざしきおよびどぞう）","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46549167,"lng":135.86283333,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造２階建、瓦葺、建築面積44㎡","structure_material":"木造２階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0292","desc":"客殿及び庫裏の北西に建つ。東を入母屋造の小座敷、西を切妻造置屋根の土蔵とする。小座敷は６畳で北に床、棚、押入を備え、南から東へ濡縁を廻し、土蔵側は半間幅の蔵前廊下である。土蔵は二階建で外壁は腰を焼板の竪羽目板張とするほかは漆喰塗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013310"},{"id":"00013309","register_sub_id":"101","register_pk":"366298","name":"旧慈門院持仏堂（陶原家住宅持仏堂）","kana":"きゅうじもんいんじぶつどう（すはらけじゅうたくじぶつどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46549167,"lng":135.86300278,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0291","desc":"客殿の北方に建つ持仏堂。梁間二間、桁行三間の規模で東を正面とし、北面を除く三方に濡縁を廻らす。屋根は入母屋造桟瓦葺妻入。内部は畳敷の一室で、中央北寄りに厨子、西、北面に仏壇を据える。天井中央を折上げ護摩用の煙抜きを設ける。丁寧な造作の小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013309"},{"id":"00013312","register_sub_id":"101","register_pk":"366301","name":"旧慈門院塀重門（陶原家住宅塀重門）","kana":"きゅうじもんいんへいじゅうもん（すはらけじゅうたくへいじゅうもん）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46531667,"lng":135.86292222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、檜皮葺、間口1.7m、左右袖塀付","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0294","desc":"表門北面と客殿の間に建つ腕木門で、前庭と東の主庭を画す。屋根は勾配が緩やかな切妻造檜皮葺である。礎盤に円柱を立て、腕木は西正面を拳鼻とし、東は控柱で受ける。扉は花格子入の桟唐戸で、蟇股は麒麟の彫刻で飾るなど、主庭からの景色を華やかに整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013312"},{"id":"00013306","register_sub_id":"101","register_pk":"366295","name":"旧真法院表門（西宮家住宅表門）","kana":"きゅうしんぽういんおもてもん（にしみやけじゅうたくおもてもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰336","lat":34.46486111,"lng":135.85923333,"geo_status":"db","era":"嘉永2年(1849)／昭和60年頃改修","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造、瓦葺、間口2.4m、左右袖塀付","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0288","desc":"敷地南面に開く棟門。礎盤上円柱の上に冠木を載せ、女梁、男梁を組み、男梁上の舟肘木で軒桁を受ける。冠木上には板蟇股を載せ棟木を受け、妻飾は大瓶束笈形付とする。背面は舟肘木下に控柱を立てる。木柄が太く、一軒疎垂木の深い軒は力感ある外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013306"},{"id":"00013305","register_sub_id":"101","register_pk":"366294","name":"旧真法院客殿及び庫裏（西宮家住宅主屋）","kana":"きゅうしんぽういんきゃくでんおよびくり（にしみやけじゅうたくおもや）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰336","lat":34.46495,"lng":135.85936667,"geo_status":"db","era":"嘉永3年(1850)","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積311㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0287","desc":"旧妙楽寺子院が神仏分離後、社家住宅となったもの。客殿は三列九室を配し、周囲に鞘の間や縁を廻らし大規模で、南西に唐破風玄関、南東に庫裏を付す。北に床付の座敷を据え、その南は内拝所だが旧仏間で、本尊厨子は小屋裏に据えている。子院建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013305"},{"id":"00013307","register_sub_id":"101","register_pk":"366296","name":"旧真法院塀重門（西宮家住宅塀重門）","kana":"きゅうしんぽういんへいじゅうもん（にしみやけじゅうたくへいじゅうもん）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰336","lat":34.46486111,"lng":135.85923333,"geo_status":"db","era":"嘉永3年(1850)／昭和60年頃改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造、檜皮葺（銅板仮葺）、間口2.0m","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0289","desc":"客殿南妻の玄関から西に延びる土塀に開く腕木門で、前庭と北の主庭を画す。柱は角柱で、北背面に支柱を添え、柱間中央に蟇股を据え棟木を受ける。桟唐戸を木製藁座で釣込む。銅板葺だが檜皮葺の軒付を残し、一軒疎垂木とともに軽快な印象で前庭の景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013307"},{"id":"00005023","register_sub_id":"101","register_pk":"106013","name":"浄教寺掲示板舎","kana":"じょうきょうじけいじばんしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市上三条町","lat":34.68204176,"lng":135.82517849,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、銅板葺、間口1.1m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0090","desc":"山門前方西側に三条通りに面して建つ。柱間１間，切妻造，銅板葺で，切石基壇の上に建つ。柱背面に鉄棒の控えが付き，柱正面で木鼻状の受木が掲示板額縁を受ける。基壇葛石上に木柵を巡らせる。細部も丁寧なつくりで，三条通りの歴史的景観の構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005023"},{"id":"00005022","register_sub_id":"101","register_pk":"106012","name":"浄教寺山門","kana":"じょうきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市上三条町","lat":34.68209107,"lng":135.82522831,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0089","desc":"三条通りに南面して建つ。１間１戸の薬医門で，屋根は切妻造，本瓦葺，軒は二軒繁垂木とし，主柱は唐居敷に円柱を建てる。蟇股・木鼻・桟唐戸綿板等の各所に動植物・渦・雲等の彫刻を施す。均整のとれたつくりで，三条通りの歴史的景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005022"},{"id":"00014507","register_sub_id":"101","register_pk":"513921","name":"浄楽寺本堂","kana":"じょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市中町279","lat":34.52668056,"lng":135.81088056,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0338","desc":"耳成山北方の農村集落中央に所在する浄土真宗寺院の本堂。入母屋造平入本瓦葺、向拝を付し、正面側三方に縁を巡らす外陣、左右余間を配す内陣からなる後門形式平面。多武峰妙楽寺輪蔵の部材を購入して建て、礎盤等は転用が明らか。神仏分離の時代を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014507"},{"id":"00014508","register_sub_id":"101","register_pk":"513922","name":"浄楽寺門","kana":"じょうらくじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県橿原市中町279","lat":34.52666111,"lng":135.81106944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0339","desc":"境内東辺の通りに開く浄土真宗寺院の薬医門で、位置を本堂軸線から少し南にずらす。本瓦葺、一軒疎垂木、五平の本柱間に冠木を架け女梁で支持する男梁で控え柱と繋ぐ。木鼻や蟇股の絵様は伝統的で質実な造形。集落中央に位置し本堂と共に歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014508"},{"id":"00016583","register_sub_id":"101","register_pk":"574945","name":"善行寺客殿","kana":"ぜんぎょうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"明治中期／平成11年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0377","desc":"本堂の東に南面して建つ貴賓用の客殿。入母屋造妻入本瓦葺で銅板葺の軒唐破風を付し、式台を構える。内部は南北３室からなり、北端室は上段に構えて格天井を張り、床・違棚・付書院を備える。式台や上段など寺格を示し、本堂と並び建ち境内景観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016583"},{"id":"00016589","register_sub_id":"101","register_pk":"574951","name":"善行寺山門","kana":"ぜんぎょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"寛政10年（1798）","year":1798,"year_source":"db","year_min":1798,"year_max":1798,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0383","desc":"境内南辺西寄りに位置し、通りより引き込み建つ一間一戸薬医門。東脇に潜戸を設け、東・西正面に袖塀を付す。屋根本瓦葺で軒は二軒繁垂木、妻飾は虹梁大瓶束笈形付。ケヤキの良材を用い、腕木や梁先端に流麗な絵様を付し、蟇股や笈形を彫刻で飾る華やかな門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016589"},{"id":"00016586","register_sub_id":"101","register_pk":"574948","name":"善行寺集会場","kana":"ぜんぎょうじしゅうかいじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0380","desc":"境内南辺の中央に建つ集会場。北面して建つ入母屋造妻入桟瓦葺で、外壁は漆喰塗で腰はモルタル塗とする。正面にガラス戸を建て、内部は板敷の１室で棹縁天井を張り、集会室とする。簡素なつくりながら太鼓楼に並び建ち、境内の歴史的景観を形成する集会場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016586"},{"id":"00016590","register_sub_id":"101","register_pk":"574952","name":"善行寺小門","kana":"ぜんぎょうじしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和4年／平成10年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、瓦葺、間口2.1m、袖塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0384","desc":"境内南面の東寄りに建つ一間一戸の薬医門。切妻造本瓦葺で、西側と東側前方に桟瓦葺袖塀を付す。主柱と控柱を貫で固め、軒は一軒疎垂木とし、板張天井で、門口に両開の板扉を吊る。小規模ながら本瓦葺屋根の重厚な外観で、通りの歴史的な景観に寄与する小門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016590"},{"id":"00016585","register_sub_id":"101","register_pk":"574947","name":"善行寺鐘楼","kana":"ぜんぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"天保10年（1839）／昭和13年改修","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造、瓦葺、面積7.7㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0379","desc":"境内南西隅に位置する鐘楼。切石積基壇に建つ入母屋造本瓦葺、円柱を四方転びに立て、腰貫、内法貫、虹梁形頭貫で固めて台輪を廻らし、組物は出組、軒は二軒繁垂木とする。内部は石敷の土間で小組格天井を張り、梵鐘を吊る。蟇股や獅子鼻など彫刻優秀な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016585"},{"id":"00016587","register_sub_id":"101","register_pk":"574949","name":"善行寺太鼓楼","kana":"ぜんぎょうじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0381","desc":"集会所の西に位置する太鼓楼。入母屋造の棟中央に方一間入母屋造の二階を載せ、全体本瓦葺。二階外壁は漆喰塗で軒まで塗込め、四面に火灯窓を開ける。二階内部は一室の畳敷で、棹縁天井を張り、上部中央に太鼓を吊る。城郭風の外観が真宗寺院の象徴的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016587"},{"id":"00016588","register_sub_id":"101","register_pk":"574950","name":"善行寺手水舎","kana":"ぜんぎょうじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、面積3.8㎡、井戸及び手水鉢付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0382","desc":"本堂の南に位置する手水舎。切妻造桟瓦葺の南北棟で、成の高い礎石上に角柱を四方転びに立て、梁と桁を架け、各間に内法貫を入れて固める。軒は一軒疎垂木で化粧屋根裏とする。内部は南に井戸、北に手水鉢を配す。簡素ながらも境内景観に欠かせない手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016588"},{"id":"00016593","register_sub_id":"101","register_pk":"574955","name":"善行寺西面北塀","kana":"ぜんぎょうじにしめんきたべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、瓦葺、延長14m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0387","desc":"本堂と宝蔵の間に建ち、境内西面の北側部分を画す塀。木造、延長１４メートル。自然石積基礎で土台上に半間毎に柱を立て内側に控柱を付す。腕木で軒を支え、屋根桟瓦葺。外壁は漆喰塗で腰はモルタル塗とする。簡素ながらも寺院境内の歴史的景観をつくる塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016593"},{"id":"00016592","register_sub_id":"101","register_pk":"574954","name":"善行寺西面南塀","kana":"ぜんぎょうじにしめんみなみべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"コンクリートブロック造、瓦葺、延長12m","structure_material":"コンクリートブロック造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0386","desc":"敷地南面西塀から宝蔵の間に建ち、境内西面南半を画す塀。延長12メートル、自然石基礎としたコンクリートブロック造の塀で屋根桟瓦葺。外壁は外を黄土色モルタル塗で５筋の定規筋を付し、内を漆喰塗仕上とする。重厚な外観で寺院境内の表構えをつくる塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016592"},{"id":"00016584","register_sub_id":"101","register_pk":"574946","name":"善行寺宝蔵","kana":"ぜんぎょうじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0378","desc":"境内西辺の南寄りに位置する宝蔵。東面して石積基礎に建つ、土蔵造２階建宝形造桟瓦葺で頂部に露盤宝珠を飾り、正面銅板葺庇に軒唐破風を付す。外壁は漆喰塗で、腰は海鼠壁とする。内部は各階板敷とし、二階は棹縁天井を張る。重厚な外観で寺観を整える宝蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016584"},{"id":"00016582","register_sub_id":"101","register_pk":"574944","name":"善行寺本堂","kana":"ぜんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"安政7年（1860）／昭和12年改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積432㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0376","desc":"藤原宮跡の南西に位置する浄土真宗寺院の本堂。境内北西に南面して建つ、入母屋造本瓦葺で正面に一間向拝を付す。典型的な真宗寺院本堂の平面形式で、外陣は円柱を立て、差物を縦横に架けて固め、内陣廻りは彫刻や彩色で荘厳を極めた江戸末期の大規模な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016582"},{"id":"00016591","register_sub_id":"101","register_pk":"574953","name":"善行寺南面西塀","kana":"ぜんぎょうじみなみめんにしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、瓦葺、延長5.6m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0385","desc":"山門袖塀の西側に続き、境内南辺の西端部を画す塀。延長５・６メートル、切石積基礎に半間毎に柱を立て、腕木で軒を支える。外は本瓦葺、壁は漆喰塗で腰は竪板張、内は桟瓦葺、壁はモルタル塗仕上とする。通りに面して真宗寺院の歴史的景観を形成する塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016591"},{"id":"00008159","register_sub_id":"101","register_pk":"132600","name":"當麻寺松室院客殿","kana":"たいまでらまつむろいんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1263-11","lat":34.51551375,"lng":135.69612641,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"29 － 0188","desc":"中之坊の東に建ち、桁行１８ｍ梁間１２ｍ、木造平屋建、入母屋造桟瓦葺で、玄関の屋根を切り上げる。内部は仏間や客間の周囲に縁をめぐらす。数寄屋建築に造詣のあった川上邦基と古代建築に精通した大岡實の設計になり、軽快さと雄大さを併せもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008159"},{"id":"00006042","register_sub_id":"101","register_pk":"107027","name":"中宮寺表御殿","kana":"ちゅうぐうじおもてごもん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺北1-1-2","lat":34.61483097,"lng":135.73945756,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"29 － 0114","desc":"敷地の中央に位置し，本堂の北側に西面して建つ。桁行６間，梁間４間半，木造平屋建，入母屋造，本瓦葺。南東隅に御上段の間を設け格天井とし，北東隅に御座の間等計６室を配する。貼付壁や襖絵等上質で，細部意匠等，書院建築の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006042"},{"id":"00013304","register_sub_id":"101","register_pk":"366293","name":"登彌神社社務所","kana":"とみじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66097222,"lng":135.76597778,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0286","desc":"境内南東に西面して建つ。南北棟の入母屋造桟瓦葺で、正面中央に向唐破風屋根の式台玄関を付し、背面南側に切妻造の角屋を突出する。内部は諸室を続間に配し、北室を床を構えた供進使室とする。装飾を抑えた端正なつくりで、境内景観を格式高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013304"},{"id":"00013302","register_sub_id":"101","register_pk":"366291","name":"登彌神社神饌所","kana":"とみじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66116667,"lng":135.76563611,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0284","desc":"本殿南西の中段に東面して建つ。桁行三間、梁間二間、切妻造桟瓦葺で、南面東間の戸口に檜皮葺の庇を付す。外壁は漆喰塗で、側背面の腰を竪板張とする。内部北側の板間西面に神饌棚を設ける。全体的に均整の取れたつくりで、本殿廻りの境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013302"},{"id":"00013303","register_sub_id":"101","register_pk":"366292","name":"登彌神社手水舎","kana":"とみじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66096944,"lng":135.76566111,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.6㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0285","desc":"境内南西に南北棟で建つ。切妻造本瓦葺、吹放し形式の長方形平面で、中ほどに手水鉢を据える。角柱を内転びに立て、正面を内法貫、側背面を内法貫と腰貫で固める。簡素ながら堅実なつくりで、境内景観の一画を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013303"},{"id":"00013301","register_sub_id":"101","register_pk":"366290","name":"登彌神社拝殿","kana":"とみじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66106389,"lng":135.76578056,"geo_status":"db","era":"寛政11年（1799）頃／昭和14年改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0283","desc":"本殿正面の石段下に建ち、旧神楽殿を改修したとされる拝殿。桁行三間、梁間二間、入母屋造桟瓦葺で、柱間装置を設けず開放的につくる。内部は板敷で化粧屋根裏とし、四周の切目縁に高欄を設ける。簡素ながらも堅実なつくりで、本殿前の礼拝空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013301"},{"id":"00013300","register_sub_id":"101","register_pk":"366289","name":"登彌神社本殿","kana":"とみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66123889,"lng":135.76582778,"geo_status":"db","era":"文政7年（1824）","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0282","desc":"市西部の丘上にある神社。本殿は境内最奥上段に南面して建つ。一間社春日造檜皮葺の二棟を、背面通りの壁面と板床で連結した特異な形式。それぞれ正側面に縁を廻して浜縁を設け、軸部は弁柄塗を基調に柱金襴巻や組物などを極彩色で彩る華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013300"},{"id":"00014195","register_sub_id":"101","register_pk":"508825","name":"中之坊稲荷社","kana":"なかのぼういなりしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1263-11","lat":34.51569722,"lng":135.69525,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"29-0331","desc":"當麻寺中之坊の境内北西隅に建つ鎮守社。一間社入母屋造平入檜皮葺、二軒繁垂木で、正面に千鳥破風を付け向拝を唐破風とする。組物は二手先で、肘木に笹繰を取り隅尾垂木を入れ向拝虹梁木鼻を波形に造り、軸部全体に彩色を施すなど、小品ながら装飾性に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014195"},{"id":"00008023","register_sub_id":"101","register_pk":"128854","name":"本善寺御成御殿","kana":"ほんぜんじおなりごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39271656,"lng":135.85901738,"geo_status":"db","era":"明和9","year":1772,"year_source":"db","year_min":1772,"year_max":1772,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0157","desc":"客殿の南に接続し、桁行９．０ｍ梁間８．０ｍ、北切妻造及び南入母屋造、桟瓦葺である。トコと違棚、付書院を備えた八畳の主室と四畳の前室からなり、西・南に広縁、周囲に落縁を巡らす。良材を用い、丁寧に造られる。客殿と一体で上質な接客空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008023"},{"id":"00008022","register_sub_id":"101","register_pk":"128853","name":"本善寺客殿","kana":"ほんぜんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39282003,"lng":135.85895403,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積227㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0156","desc":"本堂西にあって、玄関と御成御殿の間に建つ。桁行１６ｍ梁間１３ｍ、北入母屋造及び南切妻造、桟瓦葺。東西二列になり、東側は南端を上段の間とする対面所で広縁を付設する。西側は三室を並べ南室にトコ飾りを備える。対面等に用いられた大型の客殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008022"},{"id":"00008018","register_sub_id":"101","register_pk":"128849","name":"本善寺経蔵","kana":"ほんぜんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.3934556,"lng":135.85950092,"geo_status":"db","era":"寛政4","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡、輪蔵付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0152","desc":"境内東北角の野面石積基壇に建つ。桁行三間梁間三間、宝形造、西面軒唐破風付、本瓦葺である。西面中央に桟唐戸をたて、両脇間及び側面中央間に花頭窓を付ける。内部は一室で、棹縁天井を張り、八角輪蔵を納める。落ち着いた外観になる経蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008018"},{"id":"00008024","register_sub_id":"101","register_pk":"128855","name":"本善寺庫裏","kana":"ほんぜんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39287915,"lng":135.85871754,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0158","desc":"客殿の北西隅に接続して建つ。桁行１８ｍ梁間１３ｍ、入母屋造本瓦葺で、棟上に入母屋屋根の煙出を上げ、北面の東寄りに式台玄関を構える。西半部を広い土間、東を床上とし、畳敷の居室や板間を配する。地方における中核寺院の伽藍を構成する重要な要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008024"},{"id":"00008021","register_sub_id":"101","register_pk":"128852","name":"本善寺玄関","kana":"ほんぜんじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39294672,"lng":135.8589477,"geo_status":"db","era":"安政7","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積86㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0155","desc":"客殿の北正面に構える玄関で、桁行６．６ｍ梁間４．５ｍ、切妻造、正面唐破風造、檜皮葺とし、東側に下屋を張り出す。特異な屋根形状とともに、内法には波に麒麟や飛龍の透彫欄間を入れ、虹梁上に力士像を置くなど、間口が広く華やかな正面構えをもつ式台玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008021"},{"id":"00008025","register_sub_id":"101","register_pk":"128856","name":"本善寺山門","kana":"ほんぜんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39327612,"lng":135.85923909,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"29-0159","desc":"境内北面東寄りの石段上に建ち、左右に築地塀を矩折れに延ばす。一間薬医門、切妻造本瓦葺。女梁両端に大振りの絵様繰形を造り出して男梁を支持し、両妻と冠木中央に板蟇股を置いて棟木を受ける。古刹の境内入口に相応しい、木太く重厚な構えの山門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008025"},{"id":"00008019","register_sub_id":"101","register_pk":"128850","name":"本善寺鐘楼","kana":"ほんぜんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39336692,"lng":135.85928977,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、面積9.2㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0153","desc":"境内東寄り、山門東側の切石積基壇上に建つ、桁行一間梁間一間の吹放ち鐘楼。石製礎盤上に四本柱を内転びに建て、虹梁や貫で固め、柱間中央に大瓶束を入れ、組物は出組、中備を簑束、二軒半繁垂木とする。重厚な入母屋造本瓦葺とし、境内入口の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008019"},{"id":"00008020","register_sub_id":"101","register_pk":"128851","name":"本善寺茶所","kana":"ほんぜんじちゃじょ","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39322333,"lng":135.85911029,"geo_status":"db","era":"寛政10","year":1798,"year_source":"db","year_min":1798,"year_max":1798,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡、太鼓楼付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0154","desc":"本堂の北東、山門の西側に建つ。桁行７．９ｍ梁間７．０ｍ、入母屋造本瓦葺で、棟上に入母屋屋根の太鼓楼を載せる。内部は前半部を吹放ちの土間と広縁とし、竈を築く。門徒接遇のための茶所で、屋根に太鼓楼を置き、浄土真宗特有の伽藍景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008020"},{"id":"00008015","register_sub_id":"101","register_pk":"128846","name":"本善寺本堂","kana":"ほんぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.3929974,"lng":135.85916096,"geo_status":"db","era":"江戸中期／文化6・明治33改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積448㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0149","desc":"吉野川南岸に迫る山麓に占める境内の中央に建つ。桁行１８ｍ梁間１７ｍ、入母屋造本瓦葺で、正面に一間向拝を付ける。外陣と、内陣及び余間、鞘の間、後方の後堂からなり、外陣三方に広縁を巡らす。真宗の吉野地方における中核寺院に相応しい風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008015"},{"id":"00008016","register_sub_id":"101","register_pk":"128847","name":"本善寺蓮如堂","kana":"ほんぜんじれんにょどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39319588,"lng":135.85954526,"geo_status":"db","era":"延享4","year":1747,"year_source":"db","year_min":1747,"year_max":1747,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.2㎡、繋廊付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0150","desc":"境内東寄りの山裾に建ち、桁行一間梁間一間、宝形造、正面向拝一間、軒唐破風付、銅板葺である。三方に高欄付切目縁を巡らして脇障子を建て、側面に花頭窓を付け、正面桟唐戸は彫刻で飾る。小規模ながら、開祖を祀る仏堂らしく華やかな意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008016"},{"id":"00008017","register_sub_id":"101","register_pk":"128848","name":"本善寺蓮如堂拝堂","kana":"ほんぜんじれんにょどうはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39329935,"lng":135.85946925,"geo_status":"db","era":"延享5","year":1748,"year_source":"db","year_min":1748,"year_max":1748,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0151","desc":"蓮如堂の前面に繋廊を介して建ち、桁行三間梁間二間、入母屋造本瓦葺である。内部は拭板張の一室で格天井を張り、周囲に切目縁をまわす。建具は正面に桟唐戸をたて、他を蔀とし、小壁を漆喰仕上げ、軒は一軒疎垂木。軽快な堂で、柱上の絵様肘木が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008017"},{"id":"00008050","register_sub_id":"101","register_pk":"128881","name":"吉野神宮表鳥居","kana":"よしのじんぐうおもてとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県吉野郡吉野町大字吉野山3226","lat":34.38733148,"lng":135.84532564,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"石造、間口5.5m、高さ5.9m","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"29-0184","desc":"境内の北東、表参道正面に位置し、県道に北面する。石造の明神鳥居で、幅５．５ｍ高さ５．９ｍ。内転びに円柱を建て、貫と嶋木で固め、笠木を載せる。大鳥居と比べ、内転びが大きく、柱間と高さの比例もやや低く、重厚で安定感のある姿をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008050"},{"id":"00015500","register_sub_id":"101","register_pk":"533515","name":"興国寺開山堂","kana":"こうこくじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97746389,"lng":135.12491944,"geo_status":"db","era":"文政6年（1823）頃","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0408","desc":"伽藍北方の高台に位置する開山堂。宝形造本瓦葺の三間堂で周囲に縁を廻らす。組物は出組で軒支輪を備え軒は二軒繁垂木。内部は一室で北に仏壇を構え格天井を張る。仏壇下方には開祖法燈国師の墓である宝篋印塔を安置。小規模ながらも総ヒノキ造の上質な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015500"},{"id":"00015499","register_sub_id":"101","register_pk":"533514","name":"興国寺坐禅堂","kana":"こうこくじざぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97731111,"lng":135.12508333,"geo_status":"db","era":"江戸後期／江戸末期増築、昭和59年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0407","desc":"法堂の北に南面して建つ仏堂。入母屋造本瓦葺東西棟の前堂に南北棟の後堂が接続し、全体Ｔ字形の平面。内部は前堂から後堂まで一連の四半敷土間とし、前堂両端間に畳敷の単、後堂北面両端間に仏壇と位牌壇を設ける。伽藍軸線上に建ち、寺院景観の中核を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015499"},{"id":"00015502","register_sub_id":"101","register_pk":"533517","name":"興国寺大門","kana":"こうこくじだいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97526944,"lng":135.12623333,"geo_status":"db","era":"昭和13年／平成9年移築","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0410","desc":"伽藍南端の参道入口に南面して建つ四脚門。切妻造本瓦葺で、円柱の主柱と控柱を腰貫と頭貫で固め、柱頂に三斗を組んで妻虹梁を受け、丸桁を支持する。軒は二軒繁垂木。頭貫木鼻は牡丹の篭彫とするなど華やか。建ちが高い総ケヤキ造の門で古刹の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015502"},{"id":"00015498","register_sub_id":"101","register_pk":"533513","name":"興国寺法堂","kana":"こうこくじはっとう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97715278,"lng":135.12525278,"geo_status":"db","era":"寛政9年（1797）","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0406","desc":"由良町の山間に位置する臨済宗寺院の法堂。境内中心部に南面して建つ方五間二重入母屋造本瓦葺で正面に軒唐破風を付し、千鳥破風を飾る。内部は四半敷の土間とし、身舎背面側に須弥壇を設け、上部には広大な鏡天井を張り、龍を描く。大規模で雄大な禅宗仏殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015498"},{"id":"00015501","register_sub_id":"101","register_pk":"533516","name":"興国寺方丈","kana":"こうこくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97728333,"lng":135.12558889,"geo_status":"db","era":"元禄11年（1698）／天保9年（1838）増築","year":1698,"year_source":"db","year_min":1698,"year_max":1698,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0409","desc":"法堂の東側に西面して建つ方丈。寄棟造本瓦葺の南北棟で、西面南寄りに向唐破風造の玄関を突出する。平面は3列6室で三方に広縁を廻らし、西半は室中、北東に床、違棚、付書院を備えた座敷を配す。側通りには１間毎に柱を立てるなど古式を残す大規模な方丈。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015501"},{"id":"00016424","register_sub_id":"101","register_pk":"536491","name":"高山寺本堂","kana":"こうざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県田辺市稲成町393","lat":33.74045,"lng":135.37888333,"geo_status":"db","era":"昭和43年／平成26年改修","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造平屋建地階付、瓦葺、建築面積247㎡","structure_material":"鉄筋コンクリート造平屋建地階付","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0411","desc":"会津川沿いの高台にある真言宗寺院本堂。設計は大岡實。鉄筋コンクリート造入母屋造本瓦葺の五間堂形式で基壇に組高欄を廻らす。平面は内陣と外陣境に畳敷の中の間を配す。太い木割、柱や桁の隅延び、軒反りの曲線など、古代建築に精通した大岡實らしい仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016424"},{"id":"00010335","register_sub_id":"101","register_pk":"199108","name":"興山寺本堂","kana":"こうざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県紀の川市桃山町最上字東垣内561","lat":34.231283,"lng":135.347973,"geo_status":"db","era":"明治22年","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"30-0201","desc":"宝形造本瓦葺の三間堂で背面の庇一間を取込み、正面に向拝を付ける。柱上端を虹梁で固めて長押との間に彫刻化した蟇股を挟み、籠彫の木鼻を付す。組物は出組詰組で獅子の拳鼻を飾る。内部は一室で二重折上小組格天井を張る。豊かな彫刻で荘厳された近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010335"},{"id":"00014923","register_sub_id":"101","register_pk":"519183","name":"興禅寺庫裏","kana":"こうぜんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県西牟婁郡上富田町市ノ瀬字中ノ岡1043他","lat":33.70942778,"lng":135.46888611,"geo_status":"db","era":"天保2年(1831)／昭和後期改修","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0358","desc":"富田川南岸の高台に位置する臨済宗寺院の庫裏。北西を正面とする切妻片入母屋造妻入本瓦葺で棟上に煙出を設ける。正面妻は連子窓を開け、海老虹梁を架ける。三列に部屋を並べ、西に土間玄関、南東に二間続きの座敷、北東に台所。軸部木太く規模雄大な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014923"},{"id":"00015225","register_sub_id":"101","register_pk":"530649","name":"光臺院経蔵","kana":"こうだいいんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山649","lat":34.21686667,"lng":135.58474167,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0386","desc":"参道の西方に位置する校倉造の経蔵。切石積の基壇上に東面して建つ宝形造本瓦形銅板葺。礎石に円柱の床束を立て、井桁に組んだ台輪に校木を積んで丸桁を載せ、軒は一軒半繁垂木とする。内部は一室の板敷で猿頬天井張。同高に校木を積み上げる端正な姿の経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015225"},{"id":"00015224","register_sub_id":"101","register_pk":"530648","name":"光臺院多宝塔","kana":"こうだいいんたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山649","lat":34.21758889,"lng":135.58452778,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積6.0㎡","structure_material":"木造多宝塔","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0385","desc":"高野山五之室谷に位置する真言宗別格本山寺院の多宝塔。庭園内の築山上に建ち、下層は四方に擬宝珠高欄付縁を廻らし、組物は出組。上層は四手先とし軒は上下とも二軒扇垂木。屋根と亀腹は銅板葺。蟇股に菊花紋を掲げ、精緻なつくりで、名刹に相応しい多宝塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015224"},{"id":"00013174","register_sub_id":"101","register_pk":"368403","name":"神野阿弥陀堂","kana":"こうのあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷字東堂之前1049","lat":34.34918889,"lng":135.49143333,"geo_status":"db","era":"貞享3年（1686）／平成4年改修","year":1686,"year_source":"db","year_min":1686,"year_max":1686,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積109㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0277","desc":"葛城山間の集落北側に南面して建つ仏堂。寄棟造平入茅葺金属板仮葺の三間堂で、四周に切目縁を廻し庇柱を立てる。身舎柱はケヤキ円柱で、虹梁形頭貫を架け、組物は大斗肘木とする。側柱はクリの大面取り角柱に舟肘木である。紀北地域の村堂の事例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013174"},{"id":"00000803","register_sub_id":"101","register_pk":"101793","name":"高野山霊宝館玄関・北廊・中廊","kana":"こうやさんれいほうかんげんかん・きたろう・なかろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21138903,"lng":135.58113912,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積147㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0013","desc":"霊宝館の受付部で，中廊により紫雲殿と，北廊により放光閣と結ばれる。玄関は，正面３間の単層入母屋造，北廊・中廊は単層の吹放廊で，丸柱間に蔀戸風の腰羽目を付ける。基壇上に建つ紫雲殿と放光閣の寄り付き部の棟を上げ，流動感を生みだしているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000803"},{"id":"00000802","register_sub_id":"101","register_pk":"101792","name":"高野山霊宝館紫雲殿","kana":"こうやさんれいほうかんしうんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21119172,"lng":135.58113181,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積226㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0012","desc":"高野山開創１１００年記念として計画された宝物館で，当初は右翼を含む日の字形の配置計画であった｡設計は大江新太郎と奥本吾市｡当地の厳しい気候条件を考慮して，宝蔵を除き木造漆喰塗とする。紫雲殿は正面奥に位置する単層切妻造の建物で正殿にあたる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000802"},{"id":"00000804","register_sub_id":"101","register_pk":"101794","name":"高野山霊宝館放光閣","kana":"こうやさんれいほうかんほうこうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21138903,"lng":135.58086141,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積126㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0014","desc":"下層５間×５間，上層３間×３間の重層宝形造りで，下層は大斗・舟肘木，上層は出組の詰組とし，隅に尾垂木を付ける。西面後部を裳階付とし，内部に阿弥陀如来を納める。紫雲殿と同様，内部床はコルク張り，高窓の外側に鉄製の縦型ブラインドを設置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000804"},{"id":"00000806","register_sub_id":"101","register_pk":"101796","name":"高野山霊宝館宝蔵","kana":"こうやさんれいほうかんほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21100902,"lng":135.58089065,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積96㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0016","desc":"この棟のみ鉄筋コンクリート造とする。桁行３６尺，梁間２４尺，建坪２４坪，寄棟屋根の収蔵庫で，校倉造の形式を有する。校倉形式の鉄筋コンクリート造建築としては最初のもので，大江新太郎設計になる明治神宮宝物殿（大正１０年）の習作と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000806"},{"id":"00000805","register_sub_id":"101","register_pk":"101795","name":"高野山霊宝館南廊及西廊","kana":"こうやさんれいほうかんみなみろうおよびにしろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21119172,"lng":135.58091257,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積203㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0015","desc":"紫雲殿の西面に発し，南西隅で矩折れ放光閣の南面に接続する梁間２１尺の廊で，南西隅に宝形の隅櫓を載せてヴォリュームのバランスをとっている点に特徴がある。南廊は古文書及び美術工芸品の，隅櫓部は大師関係品の，西廊は仏像彫刻の展示室に充てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000805"},{"id":"00015361","register_sub_id":"101","register_pk":"532485","name":"金剛峯寺阿字観堂","kana":"こんごうぶじあじかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和後","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.21420833,"lng":135.58303611,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0393","desc":"応接室の北西に位置し、阿字観をおこなう道場。石庭に南面する桁行七間梁間三間切妻造平入銅板葺で周囲に縁を廻らす。中央の広間に来迎壁を設けて阿字を掲げ、左右に六畳大の子房を四室設ける。法隆寺西室などの僧房建築を参考に案出した高野山唯一の阿字観堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015361"},{"id":"00015359","register_sub_id":"101","register_pk":"532483","name":"金剛峯寺応接室（旧貴賓館附属浴室）","kana":"こんごうぶじおうせつしつ（きゅうきひんかんふぞくよくしつ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.21408333,"lng":135.58312222,"geo_status":"db","era":"昭和8年／昭和32年頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0391","desc":"奥殿の北東に位置し、旧貴賓館の浴室を曳家改修した応接室。切妻造銅板葺で四周に縁を廻し西と東に庇を付す。柱頭で軒桁を受け、軒は一軒疎垂木。妻飾は豕扠首。内部は一室の板敷で竿縁天井を張り東に床を構え石庭を望む。奥殿に続き庭園景観をつくる応接室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015359"},{"id":"00015357","register_sub_id":"101","register_pk":"532481","name":"金剛峯寺奥殿(旧貴賓館）","kana":"こんごうぶじおくでん（きゅうきひんかん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山132","lat":34.21397222,"lng":135.58291944,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積330㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0389","desc":"高野山に位置する真言宗総本山寺院の貴賓用の客殿。石庭に南面して建つ入母屋造平入銅板葺で正面に切妻造玄関を付す。二列八室の周囲に擬宝珠高欄付縁を廻らし、玄関は絨毯敷で貴賓室に用い、南西に床構え付座敷を配す。正面の大蟇股が目を惹く優雅な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015357"},{"id":"00015365","register_sub_id":"101","register_pk":"532489","name":"金剛峯寺奧殿塀","kana":"こんごうぶじおくでんへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷137","lat":34.21374444,"lng":135.58275833,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、銅板葺、延長81m","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0397","desc":"勅使門の東西に延びる延長81メートルの塀。土台上に角柱を立て、腰長押と内法長押を廻らし、北側に控柱を立て２段の貫で繋ぐ。大仏様風の繰型付き腕木で出桁を支え、軒は一軒疎垂木とし屋根銅板葺。外壁は真壁造で漆喰塗仕上。長大な塀が境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015365"},{"id":"00015360","register_sub_id":"101","register_pk":"532484","name":"金剛峯寺奥殿渡廊下","kana":"こんごうぶじおくでんわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷137","lat":34.214,"lng":135.58310278,"geo_status":"db","era":"昭和8年／昭和32年頃増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0392","desc":"奥殿、別殿及び応接室を接続する平面Ｔ字形の渡廊下。両下造銅板葺で角柱上の舟肘木で桁を支え、虹梁を架け大斗肘木で棟木を支持。軒は一軒疎垂木。柱間は吹放ちとし高欄と飛貫を入れ、板敷床で化粧軒裏を現す。軽快なつくりで周囲の建物と調和した渡廊下。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015360"},{"id":"00015496","register_sub_id":"101","register_pk":"533511","name":"金剛峯寺浄水所","kana":"こんごうぶじじょうすいじょ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷152-1","lat":34.21313333,"lng":135.5813,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積34㎡","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0404","desc":"壇上伽藍へ至る蛇腹路の南側に位置し、北面して建つ浄水所。桁行三間梁間一間、鉄筋コンクリート造切妻造瓦棒銅瓦葺で、四方を吹放つ。内部中央には水盤を据え、上部は化粧屋根裏天井を現す。内外は全て白色塗装とし、簡明ながら大規模で存在感を示す手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015496"},{"id":"00015495","register_sub_id":"101","register_pk":"533510","name":"金剛峯寺鐘楼","kana":"こんごうぶじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷152-1","lat":34.21293889,"lng":135.58003333,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積30㎡","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0403","desc":"壇上伽藍の金堂南東に位置する鐘楼。基壇上に北面して建つ、鉄筋コンクリート造入母屋造瓦棒銅瓦葺。柱を隅に寄せた方三間で四方を吹放ち、台輪上に出組を詰組に配し、軒は二軒繁垂木。細部は金堂などに通じる復古調の意匠とし、軒出が深く堂々たる姿の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015495"},{"id":"00015362","register_sub_id":"101","register_pk":"532486","name":"金剛峯寺新書院","kana":"こんごうぶじしんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.214125,"lng":135.58270278,"geo_status":"db","era":"大正前期／昭和32年移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、銅板葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0394","desc":"奥殿の北西に廊下で接続する貴賓用の離座敷。入母屋造銅板葺の南北棟で周囲に下屋を廻らし、北西に浴室を附属する。内部は三室からなり、北室は１８畳の主座敷で、床、違棚、付書院を備える。全体に良材を豊富に用い、障壁画や細部意匠に優れた華やかな座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015362"},{"id":"00015363","register_sub_id":"101","register_pk":"532487","name":"金剛峯寺真松庵","kana":"こんごうぶじしんしょうあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.21413889,"lng":135.582575,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0395","desc":"新書院の西に接続する貴賓用の茶室。八畳広間席の南東に六畳の待合棟、南西に４畳半茶室を付す。広間席の天井は疎らに組んだ格天井とし、天井板の板目を市松状に配する凝ったつくり。いずれも軒高を抑えた銅板葺屋根で、柱を面皮付とした上質なつくりの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015363"},{"id":"00015364","register_sub_id":"101","register_pk":"532488","name":"金剛峯寺勅使門","kana":"こんごうぶじちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷137","lat":34.21372778,"lng":135.58284444,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、檜皮葺、間口3.5m","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0396","desc":"奥殿正面に開く、一間一戸檜皮葺の平唐門。円柱の主柱と大面取角柱の控柱を腰貫、飛貫、男梁で繋ぎ、軒は一軒疎垂木とし、棟木を蟇股と垂木で受ける特徴的なつくり。門口に繊細な連子の板扉を開け、欄間に寺紋を飾る。螻羽深く、全体に優美で上質な勅使門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015364"},{"id":"00015358","register_sub_id":"101","register_pk":"532482","name":"金剛峯寺別殿（旧客殿）","kana":"こんごうぶじべつでん（きゅうきゃくでん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山132","lat":34.21388056,"lng":135.58321944,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積363㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"31 - 0390","desc":"奥殿の東に位置する僧侶・信徒用の客殿。石庭に西面して建つ入母屋造銅板葺で柱上に組物なく直接軒桁を受け、軒は一軒疎垂木。二列八室の周囲に刎高欄付縁を廻らし、南西を床構え付座敷とする。内向きの控え目な意匠としつつ寺格に応じた大規模で上質な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015358"},{"id":"00015494","register_sub_id":"101","register_pk":"533509","name":"金剛峯寺六角経蔵","kana":"こんごうぶじろっかくきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山152-1","lat":34.21281667,"lng":135.57895833,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造二階建、銅板葺、建築面積21㎡","structure_material":"鉄筋コンクリート造二階建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0402","desc":"金剛峯寺壇上伽藍の金堂南西に位置する経蔵。基壇上に東面して建つ鉄筋コンクリート造、二重、六角円堂で宝形造銅板葺。初重は壁式構造に木造で校倉風、二重はラーメン構造に木造で組物・軒廻りを付加するなど、躯体の表層に木造で伝統的意匠を実現した経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015494"},{"id":"00016426","register_sub_id":"101","register_pk":"536493","name":"西南院経蔵","kana":"さいなんいんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山249","lat":34.21218333,"lng":135.57477222,"geo_status":"db","era":"享和3年（1803）／昭和後期改修","year":1803,"year_source":"db","year_min":1803,"year_max":1803,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0413","desc":"境内南端の高台に北面して建つ経蔵。土蔵造二階建、入母屋造銅板葺の置屋根形式で、一階正面に唐破風造銅板葺の前室を付す。外壁は大壁で、床下は柱のみを塗込め、高床風の外観とする。前室正面に大振りの板蟇股を飾り、組物などに彩色を施した華やかな経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016426"},{"id":"00016427","register_sub_id":"101","register_pk":"536494","name":"西南院山門","kana":"さいなんいんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字西院谷249","lat":34.21286389,"lng":135.57527778,"geo_status":"db","era":"昭和45年頃","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"木造、銅板葺、間口4.5m、左右袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0414","desc":"境内東寄りに北面して建ち、表門となる四脚門。切妻造銅板葺で左右に切妻造銅板葺の袖塀を付す。門は主柱を円柱、控柱を角柱とし、軒は垂木に強い反りを付した二軒繁垂木、妻飾は虹梁蟇股。全体に均整とれた姿で、中備の蟇股など復古的な意匠でまとめた山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016427"},{"id":"00016425","register_sub_id":"101","register_pk":"536492","name":"西南院本堂","kana":"さいなんいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山249","lat":34.21240556,"lng":135.57508889,"geo_status":"db","era":"明治34年頃／昭和中期改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0412","desc":"高野山の西院谷に位置する真言宗寺院の本堂。境内南東部に北面して建つ入母屋造檜皮葺で、正面東寄りに向唐破風造向拝を付す。内部は内陣を並列する特徴的な平面で東に金剛界大日如来、西に不動明王を安置。明治３年焼失後の再建になる近代の大規模な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016425"},{"id":"00014911","register_sub_id":"101","register_pk":"519171","name":"志磨神社神門及び袖塀","kana":"しまじんじゃしんもんおよびそでへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市中之島677","lat":34.23996667,"lng":135.18076389,"geo_status":"db","era":"昭和19年","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"神門 木造、瓦葺、間口2.7m、袖塀 木造、瓦葺、総延長16m","structure_material":"神門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0346","desc":"境内南端、参道正面に建つ一間一戸の四脚門。柱は面取角柱とし、本柱を繋ぐ冠木上に巻斗を並べて棟木を支える。控柱は頭貫で繋ぎ、大斗肘木を載せる。軒は一軒疎垂木。袖塀は連子格子で腰板壁とする。整った意匠をもつ神門で袖塀とともに境内の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014911"},{"id":"00014910","register_sub_id":"101","register_pk":"519170","name":"志磨神社手水舎","kana":"しまじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市中之島677","lat":34.24003889,"lng":135.18081389,"geo_status":"db","era":"昭和19年","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.8㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0345","desc":"参道脇に西面する手水舎。方一間切妻造桟瓦葺。四隅に面取角柱を内転びに立て飛貫で固め、木鼻は大仏様風。組物を介さず柱頭に直接梁桁を架け柱間は貫上に蟇股を載せる。妻飾は豕扠首。簡素ながら洗練された意匠をもつ手水舎で、境内の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014910"},{"id":"00014909","register_sub_id":"101","register_pk":"519169","name":"志磨神社拝殿","kana":"しまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市中之島677","lat":34.24023056,"lng":135.18088889,"geo_status":"db","era":"昭和19年／昭和42年改修","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0344","desc":"和歌山城北東に位置する式内社。本殿の南側に建つ桁行五間梁間三間、入母屋造平入銅板葺で正面に三間の軒唐破風向拝を付し、背面に両下造の祝詞殿、北西に切妻造の神饌所を附属。内部は格天井とし正側面に切目縁を廻す。蟇股や虹梁絵様など整った意匠の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014909"},{"id":"00015219","register_sub_id":"101","register_pk":"530643","name":"淨願寺庫裏","kana":"じょうがんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分字廣田823-1他","lat":34.26444722,"lng":135.34344722,"geo_status":"db","era":"江戸後期／平成29年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積245㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0380","desc":"本堂の西に位置する庫裏。東面して建つ入母屋造平入桟瓦葺で、正面南寄りに唐破風造の式台玄関を付す。内部は南に土間、北に8室を配し、北西に角座敷を延ばして上段の間とし、西面に床を構え、前面に上段を設ける。大振りな式台玄関が目を惹く大規模な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015219"},{"id":"00015223","register_sub_id":"101","register_pk":"530647","name":"淨願寺山門","kana":"じょうがんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26428333,"lng":135.343675,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.2m、袖塀付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0384","desc":"境内南辺東寄りに位置し、通りに南面する山門。一間一戸切妻造平入本瓦葺の薬医門で両脇に袖塀を付し、正面側に中古の控柱を立てる。男梁上の平三斗で妻虹梁を受け、笈形付大瓶束で棟木を支持。軒は二軒繁垂木。虹梁や肘木など絵様彫刻で飾った華やかな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015223"},{"id":"00015221","register_sub_id":"101","register_pk":"530645","name":"淨願寺鐘楼","kana":"じょうがんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26429722,"lng":135.343575,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積9.0㎡","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0382","desc":"本堂の南西に位置する鐘楼。切石積基壇上に建つ方一間切妻造本瓦葺。礎盤上に角柱を四方転びに立て、腰貫、飛貫、虹梁形頭貫で固め、組物は大斗肘木、妻飾は虹梁大瓶束笈形付、軒は二軒疎垂木。虹梁・蟇股・懸魚を彫刻で飾り、総ケヤキ造とした上質な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015221"},{"id":"00015222","register_sub_id":"101","register_pk":"530646","name":"淨願寺手水舎","kana":"じょうがんじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26437222,"lng":135.34363889,"geo_status":"db","era":"江戸後期／昭和54年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積5.2㎡","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0383","desc":"本堂の南に位置する手水舎。入母屋造の本瓦葺南北棟で、角柱を四方転びに立て、虹梁形頭貫で固め、組物は大斗肘木の詰組、軒は二軒吹寄垂木とする。柱間を吹放し、土間中央西寄りに水盤を据え格天井を張る。小規模ながら降棟を付すなど重厚な屋根の手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015222"},{"id":"00015220","register_sub_id":"101","register_pk":"530644","name":"淨願寺宝蔵","kana":"じょうがんじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26431389,"lng":135.34374722,"geo_status":"db","era":"大正2年／昭和54年移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0381","desc":"本堂の南東、参道に西面して建つ宝蔵。方一間宝形造本瓦葺で露盤宝珠を飾る。外壁は漆喰塗仕上で腰は下見板張。正面は戸口に両開戸を吊り、本瓦葺庇を付す。内部は一室の板敷で三方に棚を備え、上部は束立の和小屋を現す。小規模ながら寺観を整える宝蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015220"},{"id":"00015218","register_sub_id":"101","register_pk":"530642","name":"淨願寺本堂","kana":"じょうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26451667,"lng":135.343675,"geo_status":"db","era":"天明4年(1784)／明治前期増築、昭和54年改修","year":1784,"year_source":"db","year_min":1784,"year_max":1784,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0379","desc":"紀の川中流域の集落中心部に位置する浄土真宗寺院の本堂。境内北東隅に南面して建つ入母屋造平入本瓦葺で一間向拝を付す。内部は内・外陣、左右両余間からなり、正面吹放ちの広縁付。大虹梁や欄間など彫刻で荘厳し、本瓦葺の大屋根が集落景観の核をなす本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015218"},{"id":"00015367","register_sub_id":"101","register_pk":"532491","name":"常喜院客殿","kana":"じょうきいんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷365","lat":34.21298889,"lng":135.58300556,"geo_status":"db","era":"明治前期／昭和41年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積361㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0399","desc":"本堂の東方に南面して建つ客殿。入母屋造平入銅板葺で正面東寄りに入母屋造玄関を突出。玄関を入った正面８畳間を挟んで、東に庫裏、西に客殿を接続し、客殿に持仏間、上段の間を配する。高野山における近世以来の平面的な特徴を備えた近代の大規模な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015367"},{"id":"00015369","register_sub_id":"101","register_pk":"532493","name":"常喜院山門","kana":"じょうきいんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷364","lat":34.21284167,"lng":135.58315833,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、銅板葺、間口3.5m、袖塀付","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0401","desc":"境内東辺に東面して建つ正門。切妻造銅板葺の四脚門で両脇に袖塀を付す。主柱は円柱、控柱は角柱、組物出三斗、軒は反りのある二軒疎垂木。妻飾は虹梁に束立で蟇股風笈形を付す。頭貫木鼻や蟇股などを復古的な細部意匠とし、ヒノキの良材を用いた上質な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015369"},{"id":"00015368","register_sub_id":"101","register_pk":"532492","name":"常喜院拝殿","kana":"じょうきいんはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷364","lat":34.21297778,"lng":135.58255,"geo_status":"db","era":"明治43年頃／令和6年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積268㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0400","desc":"日露戦争戦没者慰霊塔の拝殿で境内中央部に南面して建つ。入母屋造銅板葺で正背面に軒唐破風を付す。内部は3列6室に部屋を並べ、西列北は折上小組格天井の上段の間とし、上段に付書院と帳台構を備える豪壮なつくり。大振りな軒唐破風など外観華やかな拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015368"},{"id":"00015366","register_sub_id":"101","register_pk":"532490","name":"常喜院本堂（旧最勝院本堂）","kana":"じょうきいんほんどう（きゅうさいしょういんほんどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷364","lat":34.21285833,"lng":135.58224722,"geo_status":"db","era":"江戸末期／昭和41年増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、銅板葺、建築面積324㎡","structure_material":"土蔵造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0398","desc":"高野山の南谷にある真言宗寺院の本堂。境内西側に東面して建つ宝形造銅板葺主体部の北に入母屋造の護摩堂棟を延ばし、西に切妻造の増築棟を付す複雑な屋根構成。正面の外壁は桁下まで塗込め漆喰塗仕上とし、中央に掛子塗扉を開く。重厚な外観が特徴的な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015366"},{"id":"00011785","register_sub_id":"101","register_pk":"210801","name":"正住寺離れ座敷","kana":"しょうじゅうじはなれざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市東長町二丁目17他","lat":34.228235,"lng":135.163822,"geo_status":"db","era":"大正9年／平成25年移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0223","desc":"山門から本堂へと続く参道の北側に建つ。寄棟造桟瓦葺の平屋建で、座敷一〇畳、次の間七畳半の正面側及び背面側に内縁を設け、南西隅に入母屋造の玄関が取り付く。座敷廻りを杉や檜を用いて端正にまとめるなど、質の高い意匠を備える離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011785"},{"id":"00011787","register_sub_id":"101","register_pk":"210803","name":"稱念寺山門","kana":"しょうねんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市加太1346","lat":34.274809,"lng":135.07432,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.9m、左右潜戸付","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"30-0225","desc":"境内の西面に建つ四脚門。切妻造本瓦葺で、両脇には小屋根を付けた潜戸が付く。門柱は円柱とし、冠木上に中備蟇股として虹梁を支える。控柱は几帳面取角柱で、門柱との間は腰貫、腰長押、頭貫で繋ぐ。小規模ながら総欅造とするなど質の高い門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011787"},{"id":"00011786","register_sub_id":"101","register_pk":"210802","name":"稱念寺本堂","kana":"しょうねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市加太1346","lat":34.274945,"lng":135.074465,"geo_status":"db","era":"寛政7年（1795）／明治40年移築","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積343㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0224","desc":"加太の街中にある西山浄土宗寺院の本堂。入母屋造本瓦葺の七間堂で、和歌山城下にあった真光寺より移築したもの。三間規模の向拝を設け、南東には式台玄関が付く。身舎柱は円柱、庇柱は面取角柱。内陣柱は漆塗金襴巻、小壁に彫刻欄間をはめるなど荘厳な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011786"},{"id":"00006043","register_sub_id":"101","register_pk":"107028","name":"定福寺庫裏","kana":"じょうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市賢堂285","lat":34.308819,"lng":135.612625,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"30 － 0102","desc":"敷地南西に位置し，本堂南西に南面して建つ。南東隅に拝殿を付ける。桁行６間半，梁間５間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。東半を土間，西半を床上部とし，南西隅に座敷を設け続き間座敷とする。床構えに古い形式を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006043"},{"id":"00010040","register_sub_id":"101","register_pk":"196187","name":"東光寺山門","kana":"とうこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡北山村大字竹原字下モ地296","lat":33.96415242,"lng":135.97346193,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"30 － 0191","desc":"本堂の東正面に建つ四脚門形式の山門で、棟柱を若干正面側にずらし、薬医門に似た構成とする。切妻造桟瓦葺。柱上には組物を設けず、棟通りは冠木上に棟束三本を立てて斗と実肘木で棟木を受け、妻では棟束に大振りの笈形を付す。伽藍正面の景観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010040"},{"id":"00010039","register_sub_id":"101","register_pk":"196186","name":"東光寺本堂","kana":"とうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡北山村大字竹原296","lat":33.96423314,"lng":135.97332362,"geo_status":"db","era":"弘化4","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"30 － 0190","desc":"桁行九間半梁間六間、切妻造平入で、東面して建つ。方丈型本堂と庫裏を組み合わせた形式で、本堂部は五室、庫裏部は四室からなり、簡素な外観ながら、ケヤキを用いた内陣を中心とした上質な堂内をもつ。両妻にはガンギと呼ばれる板張を設け、地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010039"},{"id":"00005658","register_sub_id":"101","register_pk":"106646","name":"日本基督教団紀南教会","kana":"にほんきりすときょうだんきなんきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県東牟婁郡那智勝浦町大字下里930-1","lat":33.57937575,"lng":135.92185449,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積84㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0100","desc":"西村伊作設計の教会堂建築。間口６．４ｍ，奥行１１．７ｍ規模の単廊式教会堂で，正面中央の玄関ポーチを高く造り，急傾斜屋根を架けるのが特徴。玄関ポーチ外壁のみドイツ壁風に仕上げる。内部東面にアルコーブを設けて講壇とし，独特なトラス小屋を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005658"},{"id":"00004603","register_sub_id":"101","register_pk":"105593","name":"日本聖公会橋本基督教会旧礼拝堂","kana":"にほんせいこうかいはしもときりすときょうかいきゅうれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市古佐田1-244","lat":34.31691634,"lng":135.61255152,"geo_status":"db","era":"明治初期／明治33移築改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"30 － 0069","desc":"もと奈良県吉野にあった明治初期建築の民家。平屋建，切妻造，桟瓦葺で，平面は４間取になる。床上４室が牧師の執務と居住の用に供せられ，移築時に床を張った土間が礼拝堂になる。伝統的な民家の形式を保持しつつ，教会堂に転換された数少ない事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004603"},{"id":"00016719","register_sub_id":"101","register_pk":"579203","name":"宝城院客殿及び庫裏","kana":"ほうじょういんきゃくでんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山156","lat":34.215064,"lng":135.579567,"geo_status":"db","era":"江戸後期／昭和40年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺及び銅板葺、建築面積480㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0429","desc":"境内北寄りに位置する客殿及び庫裏。大規模な客殿の西に、庫裏を配して全体鉄板葺とし、南面西寄りに入母屋造銅板葺の式台玄関を付す。客殿の上段の間は大床を構えて障壁画を飾り、帳台構えを備えるなど格式高い構成とする。高野山における寺院客殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016719"},{"id":"00016720","register_sub_id":"101","register_pk":"579204","name":"宝城院山門","kana":"ほうじょういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字谷上156","lat":34.214814,"lng":135.579422,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、銅板葺、間口3.4m","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0430","desc":"参道正面に建つ正門。切妻造銅板葺、一間一戸の四脚門。主柱は円柱、控柱は角柱とし、組物は出三斗、軒は二軒疎垂木とする。妻の虹梁上の大瓶束は蕾形とした独特な形状で、冠木中央の束に唐獅子と牡丹の笈形を付す。彫刻優秀で、寺観を整える華やかな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016720"},{"id":"00016718","register_sub_id":"101","register_pk":"579202","name":"宝城院本堂及び護摩堂","kana":"ほうじょういんほんどうおよびごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山156","lat":34.214904,"lng":135.579695,"geo_status":"db","era":"江戸後期／昭和40年頃増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0428","desc":"壇上伽藍の北の高台に位置する真言宗寺院の本堂及び護摩堂。本堂は西面して建つ入母屋造平入で一間向拝を付し、背面に増築の内陣を突出。北に接続する護摩堂は切妻造で本堂と一連で瓦型銅板葺とし、正面に縁を廻らす。両堂の内陣が並列する高野山らしい仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016718"},{"id":"00015214","register_sub_id":"101","register_pk":"530638","name":"法然寺本堂","kana":"ほうねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市沖野々字城山553-1","lat":34.16112222,"lng":135.27710278,"geo_status":"db","era":"明治9年／平成29年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0375","desc":"貴志川西岸の高台に位置する浄土宗寺院本堂。境内中央に南面する入母屋造本瓦葺の五間堂で、正面を吹放ちの広縁とし、一間向拝を付す。組物は大斗肘木、軒は二軒疎垂木、妻飾は虹梁大瓶束。内・外陣境の虹梁上に、躍動的な龍の彫刻を横溢させた華やかな本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015214"},{"id":"00014404","register_sub_id":"101","register_pk":"511393","name":"堀越癪観音庫裏","kana":"ほりこししゃくかんのんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷字向井1360","lat":34.340125,"lng":135.5,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0329","desc":"和泉と高野山を往来する七越峠近くに所在する葛城修験行所の一つで、本堂西隣に位置する庫裏。入母屋造茅葺、西側に竈を置く土間、東側を六間取鍵座敷として縁を廻らす農家風の建物。床差し天井、おだち組の小屋など古式を示す。修験の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014404"},{"id":"00013876","register_sub_id":"101","register_pk":"507834","name":"槇尾山明神社摂社弁財天社本殿","kana":"まきおやまみょうじんしゃせっしゃべんざいてんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字九度山字東山新開619-14","lat":34.28826667,"lng":135.56758056,"geo_status":"db","era":"明和2年(1765)／平成17年改修","year":1765,"year_source":"db","year_min":1765,"year_max":1765,"year_label":null,"structure":"木造平屋建、銅板葺、5.8㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0313","desc":"本殿の北に建つ一間社春日造銅板葺。正側面に縁を廻し脇障子を建て浜床を設ける。組物は三斗で背面妻飾は豕扠首。身舎と庇は海老虹梁で繋ぐ。本殿よりやや小規模だが形式は同様で、木柄の太さや肘木の面取に古式を示す。本殿と共に産土社の遺風を伝える社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013876"},{"id":"00013875","register_sub_id":"101","register_pk":"507833","name":"槇尾山明神社本殿","kana":"まきおやまみょうじんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字九度山字東山新開619-14","lat":34.28831944,"lng":135.56761111,"geo_status":"db","era":"明和2年(1765)／平成17年改修","year":1765,"year_source":"db","year_min":1765,"year_max":1765,"year_label":null,"structure":"木造平屋建、銅板葺、8.0㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0312","desc":"槙尾山の西斜面に西面して建つ。一間社春日造銅板葺。正側面に縁を廻し脇障子を建て浜床を設ける。組物は三斗で背面妻飾は豕扠首。身舎と庇は海老虹梁で繋ぐ。正面に板唐戸を建て、内部は引違障子で前後に区画。間口二メートルを超える大型の春日造社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013875"},{"id":"00015226","register_sub_id":"101","register_pk":"530650","name":"密厳院苅萱堂","kana":"みつごんいんかるかやどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山478","lat":34.21250556,"lng":135.59298889,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、檜皮葺及び銅板葺、建築面積423㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0387","desc":"金剛峯寺の東方に所在する仏堂。北面して建つ入母屋造檜皮葺東西棟の南に入母屋造銅板葺の南北棟を接続。内部は西に引導地蔵の内陣、東に親子地蔵の内陣を配し、両内陣を結ぶ南側通路は苅萱親子の悲話の絵解き場。街路沿いに建ち地域の歴史的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015226"},{"id":"00016600","register_sub_id":"101","register_pk":"574962","name":"養源寺大黒堂","kana":"ようげんじだいこくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1465-1","lat":34.02998889,"lng":135.17308056,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡、左右渡り廊下及び連絡廊附属","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0425","desc":"本堂と妙見堂と廊下で接続し、出世大黒天を安置する仏堂。東面する入母屋造平入本瓦葺で1間向拝を付す。内陣は畳敷、外陣は拭板張でいずれも格天井。内陣中央西寄りに須弥壇を構え天井を折上げる。向拝の木鼻や手挟など精緻な彫刻で飾り外観華やかな仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016600"},{"id":"00016599","register_sub_id":"101","register_pk":"574961","name":"養源寺本堂","kana":"ようげんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1465-1","lat":34.02998889,"lng":135.17308056,"geo_status":"db","era":"正徳3年（1713）／昭和7年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0424","desc":"市街地の中心部に位置する日蓮宗寺院本堂。境内中央に東面して建つ、寄棟造平入本瓦葺で向拝一間を付し、北東に入母屋造の玄関を接続。組物は舟肘木、軒は一軒疎垂木。内陣は格天井張で来迎柱や組物を彩色で荘厳する。棟に鯱瓦を載せ古刹の風格を示す本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016599"},{"id":"00012973","register_sub_id":"101","register_pk":"368114","name":"利生護国寺山門","kana":"りしょうごこくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市隅田町下兵庫字山副732","lat":34.32420833,"lng":135.63354722,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 260","desc":"境内の南辺、本堂正面に開く１間１戸の四脚門。切妻造本瓦葺、板桟戸両開き。門柱は円柱、控柱は面取角柱とし、控柱と門柱は頭貫、腰貫、腰長押でつなぐ。控柱上に実肘木付の連三斗を備える。軒は一軒疎垂木。建ちが高く、古刹にふさわしい門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012973"},{"id":"00013878","register_sub_id":"101","register_pk":"507836","name":"楞厳寺石段及び石垣","kana":"りょうごんじいしだんおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡那智勝浦町大字大野字安之坂1422","lat":33.67346944,"lng":135.84467222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石段 石造、総延長15m、石垣 石造、総延長51m","structure_material":"石段 石造","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0315","desc":"石垣は高台の境内擁壁を兼ね、本堂前庭を囲んで東と南に入口を開ける。流紋岩を野面に積み、前庭から上部は切石積とする。総延長五四メートル。東面の入口から南に曲がる石段が取付き、東に二四段、南に二〇段を数える。山間部にある寺院境内の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013878"},{"id":"00013877","register_sub_id":"101","register_pk":"507835","name":"楞厳寺本堂","kana":"りょうごんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡那智勝浦町大字大野字安之坂1422","lat":33.673525,"lng":135.84461667,"geo_status":"db","era":"安政4年(1857)／明治後期改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0314","desc":"桁行九間梁間五間半入母屋造桟瓦葺。東面し、広縁を東南面に廻す。方丈形式で、前列は天井棹縁を通して欄間を開放とする等三室を一体的に扱う。後列は内陣両脇に脇間。長押付の貫を一木で造りだすなど堅牢なつくり。向拝や組物も無く質実な外観を有する本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013877"},{"id":"00016429","register_sub_id":"101","register_pk":"536496","name":"蓮華定院客殿及び庫裏","kana":"れんげじょういんきゃくでんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山700","lat":34.21808889,"lng":135.5816,"geo_status":"db","era":"江戸末期／昭和50年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、檜皮葺及び金属板葺、建築面積487㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0416","desc":"本堂の北東に南面して建つ客殿及び庫裏。入母屋造平入檜皮葺で、正面の東寄りに入母屋造の玄関を突出する。内部は東の庫裏、西の客殿からなり、客殿の正面に一間幅の広縁及び濡縁を付して、高欄を廻らす。高野山内における江戸時代の典型的な客殿建築の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016429"},{"id":"00016430","register_sub_id":"101","register_pk":"536497","name":"蓮華定院山門","kana":"れんげじょういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字一心院谷700","lat":34.21791667,"lng":135.58158889,"geo_status":"db","era":"万延元年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造、檜皮葺、間口3.6m、東袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0417","desc":"境内南東端に南面して建つ四脚門。切妻造檜皮葺で箱棟に鬼板を飾り、東側に潜戸付袖塀を付す。主柱は円柱、控柱は角柱で三斗を組み、軒は二軒疎垂木。獅子鼻や獏鼻、腰貫上部の牡丹唐草の透欄間など精緻な彫刻を付し、要所の錺金具とともに装飾豊富な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016430"}];
